insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('improved_sanitation', '{"en": "Population living in households that use an improved sanitation facility", "hi": "बेहतर स्वच्छता सुविधा वाले परिवारों में रहने वाली आबादी"}'::jsonb, '{"en": "Improved sanitation", "hi": "बेहतर स्वच्छता"}'::jsonb, '{"en": "Share of people (all ages) whose household uses an improved toilet facility, as defined in the NFHS fact sheets. Survey estimate, not an administrative count.", "hi": "उन लोगों (सभी आयु) का प्रतिशत जिनका परिवार NFHS की परिभाषा के अनुसार बेहतर शौचालय सुविधा का उपयोग करता है। यह सर्वेक्षण अनुमान है, प्रशासनिक गिनती नहीं।"}'::jsonb, '%', 'multiple', true, null, 1, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('electricity', '{"en": "Population living in households with electricity", "hi": "बिजली वाले परिवारों में रहने वाली आबादी"}'::jsonb, '{"en": "Electricity", "hi": "बिजली"}'::jsonb, '{"en": "Share of people (all ages) living in households that have an electricity connection. Says nothing about hours of supply.", "hi": "बिजली कनेक्शन वाले परिवारों में रहने वाले लोगों (सभी आयु) का प्रतिशत। इससे आपूर्ति के घंटों का पता नहीं चलता।"}'::jsonb, '%', 'multiple', true, null, 2, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('clean_fuel', '{"en": "Households using clean fuel for cooking", "hi": "खाना पकाने के लिए स्वच्छ ईंधन का उपयोग करने वाले परिवार"}'::jsonb, '{"en": "Clean cooking fuel", "hi": "स्वच्छ रसोई ईंधन"}'::jsonb, '{"en": "Share of households whose main cooking fuel is clean (electricity, LPG/natural gas, biogas). This is use, not just an LPG connection, so it is lower than Ujjwala connection counts.", "hi": "उन परिवारों का प्रतिशत जिनका मुख्य रसोई ईंधन स्वच्छ है (बिजली, एलपीजी/प्राकृतिक गैस, बायोगैस)। यह वास्तविक उपयोग है, केवल एलपीजी कनेक्शन नहीं, इसलिए यह उज्ज्वला कनेक्शन संख्या से कम है।"}'::jsonb, '%', 'multiple', true, null, 3, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('improved_water', '{"en": "Population living in households with an improved drinking-water source", "hi": "बेहतर पेयजल स्रोत वाले परिवारों में रहने वाली आबादी"}'::jsonb, '{"en": "Improved drinking water", "hi": "बेहतर पेयजल स्रोत"}'::jsonb, '{"en": "Includes piped water, public taps, tube wells and protected wells. It is not the same as a household tap connection (Jal Jeevan Mission), which will be added separately.", "hi": "इसमें पाइप से पानी, सार्वजनिक नल, ट्यूबवेल और सुरक्षित कुएँ शामिल हैं। यह घरेलू नल कनेक्शन (जल जीवन मिशन) के समान नहीं है, जिसे अलग से जोड़ा जाएगा।"}'::jsonb, '%', 'multiple', true, null, 4, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('women_bank_account', '{"en": "Women age 15-49 having a bank or savings account that they themselves use", "hi": "15-49 वर्ष की महिलाएँ जिनके पास स्वयं उपयोग किया जाने वाला बैंक या बचत खाता है"}'::jsonb, '{"en": "Women''s own bank account", "hi": "महिलाओं का अपना बैंक खाता"}'::jsonb, '{"en": "Share of women age 15-49 with a bank or savings account they use themselves. Covers women only, so it is not the same as Jan Dhan account totals.", "hi": "15-49 वर्ष की उन महिलाओं का प्रतिशत जिनके पास स्वयं उपयोग किया जाने वाला बैंक या बचत खाता है। यह केवल महिलाओं पर है, इसलिए जन धन खातों की कुल संख्या के समान नहीं है।"}'::jsonb, '%', 'multiple', true, null, 5, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('literacy', '{"en": "Literacy rate", "hi": "साक्षरता दर"}'::jsonb, '{"en": "Literacy", "hi": "साक्षरता"}'::jsonb, '{"en": "Share of people who can read and write with understanding in any language. The Census age base changed over time (whole population before 1951, age 5+ in 1951-1971, age 7+ from 1981), marked as breaks. UNESCO''s line covers adults 15+.", "hi": "किसी भी भाषा में समझ के साथ पढ़-लिख सकने वाले लोगों का प्रतिशत। जनगणना का आयु आधार समय के साथ बदला (1951 से पहले पूरी आबादी, 1951-1971 में 5+ आयु, 1981 से 7+ आयु), जिसे विराम के रूप में दिखाया गया है। यूनेस्को की रेखा 15+ वयस्कों की है।"}'::jsonb, '%', 'multiple', true, null, 6, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('life_expectancy', '{"en": "Life expectancy at birth", "hi": "जन्म के समय जीवन प्रत्याशा"}'::jsonb, '{"en": "Life expectancy", "hi": "जीवन प्रत्याशा"}'::jsonb, '{"en": "Average years a newborn would live if current death rates held. Census actuarial estimates cover ten-year periods; SRS life tables cover five-year periods; UN figures are annual model estimates.", "hi": "यदि वर्तमान मृत्यु दरें बनी रहें तो एक नवजात के औसत जीवन वर्ष। जनगणना बीमांकिक अनुमान दस-वर्षीय अवधि के हैं; SRS जीवन तालिकाएँ पाँच-वर्षीय अवधि की; संयुक्त राष्ट्र के आँकड़े वार्षिक मॉडल अनुमान हैं।"}'::jsonb, 'years', 'multiple', true, null, 7, '[20, 80]'::jsonb, 1, '[55, 80]'::jsonb) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('infant_mortality', '{"en": "Infant mortality rate", "hi": "शिशु मृत्यु दर"}'::jsonb, '{"en": "Infant mortality", "hi": "शिशु मृत्यु दर"}'::jsonb, '{"en": "Deaths before age one per 1,000 live births. Lower is better. SRS is India''s official series from 1971; pre-1947 registration undercounted deaths.", "hi": "प्रति 1,000 जीवित जन्मों पर एक वर्ष से पहले होने वाली मृत्यु। कम बेहतर है। SRS 1971 से भारत की आधिकारिक श्रृंखला है; 1947 से पहले के पंजीकरण में मृत्यु कम दर्ज होती थी।"}'::jsonb, 'per 1,000 live births', 'multiple', false, null, 8, '[0, 200]'::jsonb, 0, '[0, 100]'::jsonb) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('gdp_per_capita', '{"en": "GDP per person (2011 international dollars, PPP)", "hi": "प्रति व्यक्ति GDP (2011 अंतरराष्ट्रीय डॉलर, PPP)"}'::jsonb, '{"en": "GDP per person", "hi": "प्रति व्यक्ति GDP"}'::jsonb, '{"en": "Average income per person, adjusted for inflation and price levels so years can be compared (Maddison Project 2023). Before 1947 the figures are academic reconstructions: Broadberry, Custodis and Gupta (2015) for 1600-1871, Heston (1983) for 1870-1900, and Maddison (1985) for 1900-46. Treat them as estimates with wide uncertainty.", "hi": "प्रति व्यक्ति औसत आय, मुद्रास्फीति और मूल्य स्तर के लिए समायोजित ताकि वर्षों की तुलना हो सके (मैडिसन प्रोजेक्ट 2023)। 1947 से पहले के आँकड़े अकादमिक पुनर्निर्माण हैं: 1600-1871 के लिए ब्रॉडबेरी, कस्टोडिस और गुप्ता (2015), 1870-1900 के लिए हेस्टन (1983), और 1900-46 के लिए मैडिसन (1985)। इन्हें काफ़ी अनिश्चितता वाले अनुमान मानें।"}'::jsonb, '2011 int. $', 'multiple', true, null, 9, '[0, 10000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('state_income_per_capita', '{"en": "Income per person at constant prices (inflation removed): per capita net state/national income", "hi": "स्थिर मूल्यों पर प्रति व्यक्ति आय (मुद्रास्फीति हटाकर): प्रति व्यक्ति शुद्ध राज्य/राष्ट्रीय आय"}'::jsonb, '{"en": "Income per person (inflation removed)", "hi": "प्रति व्यक्ति आय (मुद्रास्फीति हटाकर)"}'::jsonb, '{"en": "Income per person valued at the prices of a base year, so inflation is removed and years can be compared within one base. Each base year (1993-94, 1999-2000, 2004-05, 2011-12, 2022-23) is a separate line: they are never joined. Net of depreciation, so lower than GDP per person. For what people earn in each year''s own rupees, see ''Income per person (today''s ₹)''.", "hi": "आधार वर्ष के मूल्यों पर प्रति व्यक्ति आय, ताकि मुद्रास्फीति हटे और एक आधार के भीतर वर्षों की तुलना हो सके। हर आधार वर्ष (1993-94, 1999-2000, 2004-05, 2011-12, 2022-23) एक अलग रेखा है: इन्हें जोड़ा नहीं जाता। मूल्यह्रास के बाद की शुद्ध आय, इसलिए प्रति व्यक्ति GDP से कम। हर वर्ष के अपने रुपयों में कमाई के लिए ''प्रति व्यक्ति आय (उसी वर्ष के ₹)'' देखें।"}'::jsonb, '₹ at fixed base-year prices', 'multiple', true, null, 10, '[0, 400000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('open_defecation', '{"en": "Households with no toilet facility (open defecation)", "hi": "बिना शौचालय सुविधा वाले परिवार (खुले में शौच)"}'::jsonb, '{"en": "Open defecation", "hi": "खुले में शौच"}'::jsonb, '{"en": "Share of households that use no toilet facility (open field, bush). Lower is better. NFHS data tabulated by The DHS Program with a standard definition across all five rounds, 1992-93 to 2019-21.", "hi": "उन परिवारों का प्रतिशत जो किसी शौचालय सुविधा का उपयोग नहीं करते (खुला मैदान, झाड़ी)। कम बेहतर है। NFHS आँकड़े, DHS प्रोग्राम द्वारा पाँचों दौर (1992-93 से 2019-21) में एक मानक परिभाषा से सारणीबद्ध।"}'::jsonb, '%', 'multiple', false, null, 2, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('toilet_any', '{"en": "Households with any toilet or latrine facility", "hi": "किसी भी शौचालय सुविधा वाले परिवार"}'::jsonb, '{"en": "Any toilet (1992-2006)", "hi": "कोई भी शौचालय (1992-2006)"}'::jsonb, '{"en": "As printed in the NFHS-1, 2 and 3 India reports. Counts any toilet, shared or not, so it is not the same as ''improved sanitation''. NFHS-1 values come from a scanned report and are lower-confidence.", "hi": "NFHS-1, 2 और 3 भारत रिपोर्ट में छपे अनुसार। कोई भी शौचालय, साझा हो या नहीं, गिना जाता है, इसलिए यह ''बेहतर स्वच्छता'' के समान नहीं है। NFHS-1 के मान स्कैन रिपोर्ट से हैं और कम विश्वसनीय हैं।"}'::jsonb, '%', 'multiple', true, null, 3, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('tap_water', '{"en": "Households whose main source of drinking water is a tap", "hi": "वे परिवार जिनका पीने के पानी का मुख्य स्रोत नल है"}'::jsonb, '{"en": "Tap water", "hi": "नल का पानी"}'::jsonb, '{"en": "Census of India houselisting: households whose main drinking-water source is tap water (2011 adds treated and untreated sources together, as printed). Not the same as Jal Jeevan Mission ''functional household tap connections''.", "hi": "भारत की जनगणना मकान सूचीकरण: वे परिवार जिनका पीने के पानी का मुख्य स्रोत नल है (2011 में उपचारित और अनुपचारित स्रोत मिलाकर, जैसा छपा है)। यह जल जीवन मिशन के ''कार्यात्मक घरेलू नल कनेक्शन'' के समान नहीं है।"}'::jsonb, '%', 'multiple', true, null, 4, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('household_banking', '{"en": "Households availing banking services", "hi": "बैंकिंग सेवाओं का लाभ उठाने वाले परिवार"}'::jsonb, '{"en": "Household banking", "hi": "घरेलू बैंकिंग"}'::jsonb, '{"en": "Census of India 2001 and 2011: households where any member has a bank account or uses banking services. Not the same as individual accounts (Findex) or Jan Dhan totals.", "hi": "भारत की जनगणना 2001 और 2011: वे परिवार जिनके किसी सदस्य का बैंक खाता है या जो बैंकिंग सेवाओं का उपयोग करते हैं। यह व्यक्तिगत खातों (फ़िंडेक्स) या जन धन के कुल योग के समान नहीं है।"}'::jsonb, '%', 'multiple', true, null, 6, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('toilet_premises', '{"en": "Households with a latrine within the premises", "hi": "परिसर के भीतर शौचालय वाले परिवार"}'::jsonb, '{"en": "Toilet at home (Census)", "hi": "घर में शौचालय (जनगणना)"}'::jsonb, '{"en": "Census of India: 2001 asked about a latrine ''within the house'', 2011 ''within the premises''. ORGI compares the two directly.", "hi": "भारत की जनगणना: 2001 में ''घर के भीतर'' शौचालय के बारे में पूछा गया, 2011 में ''परिसर के भीतर''। ORGI दोनों की सीधे तुलना करता है।"}'::jsonb, '%', 'multiple', true, null, 3, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('income_per_capita_current', '{"en": "Income per person in each year''s own rupees (current prices): per capita net state/national income", "hi": "हर वर्ष के अपने रुपयों में प्रति व्यक्ति आय (चालू मूल्य): प्रति व्यक्ति शुद्ध राज्य/राष्ट्रीय आय"}'::jsonb, '{"en": "Income per person (today''s ₹)", "hi": "प्रति व्यक्ति आय (उसी वर्ष के ₹)"}'::jsonb, '{"en": "What the average income per person was in that year''s rupees. Includes inflation, so growth here is larger than real growth. Base-year revisions (2011-12, 2022-23) are marked as breaks. Divide by that year''s exchange rate to get US dollars.", "hi": "उस वर्ष के रुपयों में प्रति व्यक्ति औसत आय। इसमें मुद्रास्फीति शामिल है, इसलिए यहाँ वृद्धि वास्तविक वृद्धि से अधिक दिखती है। आधार-वर्ष संशोधन (2011-12, 2022-23) विराम के रूप में चिह्नित हैं। अमेरिकी डॉलर के लिए उस वर्ष की विनिमय दर से भाग दें।"}'::jsonb, '₹ (that year''s prices)', 'multiple', true, null, 9, '[0, 600000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('tap_water_rural_jjm', '{"en": "Rural households with a tap water connection, as reported under Jal Jeevan Mission", "hi": "ग्रामीण परिवार जिनके घर में नल का कनेक्शन है, जल जीवन मिशन के अंतर्गत बताए अनुसार"}'::jsonb, '{"en": "Tap connections (JJM)", "hi": "नल कनेक्शन (जल जीवन मिशन)"}'::jsonb, '{"en": "Share of rural households that States/UTs report on the JJM-IMIS as having a household tap connection, as printed in the Ministry of Jal Shakti''s Lok Sabha answers on the stated ''as on'' date. Administrative data: it counts connections provided, not whether water is supplied regularly or is safe. Not comparable with survey or Census figures.", "hi": "ग्रामीण परिवारों का वह प्रतिशत जिनके घर में नल कनेक्शन होने की जानकारी राज्यों/केंद्रशासित प्रदेशों ने JJM-IMIS पर दी है, जैसा जल शक्ति मंत्रालय के लोकसभा उत्तरों में बताई गई तिथि के अनुसार छपा है। यह प्रशासनिक आँकड़ा है: इसमें दिए गए कनेक्शन गिने जाते हैं, यह नहीं कि पानी नियमित या सुरक्षित मिलता है। सर्वेक्षण या जनगणना के आँकड़ों से तुलनीय नहीं।"}'::jsonb, '%', 'multiple', true, null, 20, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('toilet_coverage_sbm', '{"en": "Rural households with an individual household toilet, as reported under Swachh Bharat Mission (Gramin)", "hi": "ग्रामीण परिवार जिनके पास अपना घरेलू शौचालय है, स्वच्छ भारत मिशन (ग्रामीण) के अंतर्गत बताए अनुसार"}'::jsonb, '{"en": "Toilet coverage (SBM-G)", "hi": "शौचालय कवरेज (स्वच्छ भारत मिशन-ग्रामीण)"}'::jsonb, '{"en": "Sanitation coverage: share of rural households on the SBM(G) baseline list that States/UTs report as having an individual household latrine, as printed in Lok Sabha answers on the stated ''as on'' date. Administrative data: it counts toilets built, not their use. The baseline was revised in 2017, so values before and after are on different denominators.", "hi": "स्वच्छता कवरेज: SBM(G) की आधार सूची के ग्रामीण परिवारों का वह प्रतिशत जिनके पास घरेलू शौचालय होने की जानकारी राज्यों/केंद्रशासित प्रदेशों ने दी है, जैसा लोकसभा उत्तरों में बताई गई तिथि के अनुसार छपा है। यह प्रशासनिक आँकड़ा है: इसमें बने शौचालय गिने जाते हैं, उनका उपयोग नहीं। आधार सूची 2017 में संशोधित हुई, इसलिए उससे पहले और बाद के आँकड़ों का आधार अलग है।"}'::jsonb, '%', 'multiple', true, null, 21, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('electrified_hh_admin', '{"en": "Households electrified, as informed by States under Saubhagya", "hi": "बिजली कनेक्शन वाले परिवार, सौभाग्य योजना के अंतर्गत राज्यों द्वारा बताए अनुसार"}'::jsonb, '{"en": "Household electrification (Saubhagya)", "hi": "घरों का विद्युतीकरण (सौभाग्य)"}'::jsonb, '{"en": "Household electrification percentage as informed by the States to the Ministry of Power under Saubhagya (Pradhan Mantri Sahaj Bijli Har Ghar Yojana), as printed in a Lok Sabha answer on the stated ''as on'' date. Administrative data: it counts connections given, not hours of supply. Not comparable with survey or Census figures.", "hi": "सौभाग्य (प्रधानमंत्री सहज बिजली हर घर योजना) के अंतर्गत राज्यों द्वारा बिजली मंत्रालय को बताया गया घरों के विद्युतीकरण का प्रतिशत, जैसा लोकसभा उत्तर में बताई गई तिथि के अनुसार छपा है। यह प्रशासनिक आँकड़ा है: इसमें दिए गए कनेक्शन गिने जाते हैं, बिजली आपूर्ति के घंटे नहीं। सर्वेक्षण या जनगणना के आँकड़ों से तुलनीय नहीं।"}'::jsonb, '%', 'multiple', true, null, 22, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('milex_usd_bn_constant', '{"en": "Military expenditure in billions of US dollars at constant 2024 prices and exchange rates (SIPRI)", "hi": "स्थिर 2024 मूल्यों और विनिमय दरों पर अरब अमेरिकी डॉलर में सैन्य व्यय (SIPRI)"}'::jsonb, '{"en": "Military spending (constant US$)", "hi": "सैन्य व्यय (स्थिर अमेरिकी डॉलर)"}'::jsonb, '{"en": "SIPRI''s estimate of all military spending, including the paramilitary forces it counts for India (BSF, CRPF, Assam Rifles, ITBP, SSB) and military pensions, but not military nuclear activities. Calendar years. Constant dollars remove inflation, so years can be compared. SIPRI calls military spending an input, not a measure of military capability or security. Pre-1988 figures are SIPRI estimates. The price base changes with each SIPRI edition. Neither direction is ''better'': higher_is_better is set to false only because the field needs a value.", "hi": "SIPRI का कुल सैन्य व्यय का अनुमान, जिसमें भारत के लिए गिने गए अर्धसैनिक बल (BSF, CRPF, असम राइफल्स, ITBP, SSB) और सैन्य पेंशन शामिल हैं, पर सैन्य परमाणु गतिविधियाँ नहीं। कैलेंडर वर्ष। स्थिर डॉलर मुद्रास्फीति हटाते हैं, इसलिए वर्षों की तुलना हो सकती है। SIPRI के अनुसार सैन्य व्यय एक इनपुट है, सैन्य क्षमता या सुरक्षा का माप नहीं। 1988 से पहले के आँकड़े SIPRI के अनुमान हैं। हर SIPRI संस्करण के साथ मूल्य-आधार बदलता है। इसमें कोई भी दिशा ''बेहतर'' नहीं है: higher_is_better को केवल इसलिए false रखा गया है क्योंकि इस क्षेत्र में कोई मान देना ज़रूरी है।"}'::jsonb, 'US$ bn (constant 2024 prices)', 'multiple', false, null, 1, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('milex_inr_cr_current', '{"en": "Military expenditure in rupees crore at current prices, by financial year (SIPRI)", "hi": "चालू मूल्यों पर करोड़ रुपये में सैन्य व्यय, वित्त वर्ष के अनुसार (SIPRI)"}'::jsonb, '{"en": "Military spending (₹, current)", "hi": "सैन्य व्यय (₹, चालू)"}'::jsonb, '{"en": "SIPRI''s military spending figure for India in that year''s rupees, for the April-March financial year. Includes inflation. Uses SIPRI''s definition (paramilitary forces and pensions in, military nuclear activities out), so it is larger than the Ministry of Defence budget. SIPRI calls military spending an input, not a measure of military capability or security. Neither direction is ''better'': higher_is_better is set to false only because the field needs a value.", "hi": "भारत के लिए SIPRI का सैन्य व्यय, उस वर्ष के रुपयों में, अप्रैल-मार्च वित्त वर्ष के लिए। इसमें मुद्रास्फीति शामिल है। SIPRI की परिभाषा (अर्धसैनिक बल और पेंशन शामिल, सैन्य परमाणु गतिविधियाँ बाहर) के कारण यह रक्षा मंत्रालय के बजट से बड़ा है। SIPRI के अनुसार सैन्य व्यय एक इनपुट है, सैन्य क्षमता या सुरक्षा का माप नहीं। इसमें कोई भी दिशा ''बेहतर'' नहीं है: higher_is_better को केवल इसलिए false रखा गया है क्योंकि इस क्षेत्र में कोई मान देना ज़रूरी है।"}'::jsonb, '₹ crore (current prices)', 'multiple', false, null, 2, '[0, 900000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('milex_pct_gdp', '{"en": "Military expenditure as a share of gross domestic product", "hi": "सकल घरेलू उत्पाद के हिस्से के रूप में सैन्य व्यय"}'::jsonb, '{"en": "Military spending, % of GDP", "hi": "सैन्य व्यय, GDP का %"}'::jsonb, '{"en": "SIPRI military spending divided by GDP, calendar years. The World Bank republishes the same SIPRI figures; both are shown as separate lines. A rough measure of the burden on the economy; SIPRI calls military spending an input, not a measure of military capability or security. Neither direction is ''better'': higher_is_better is set to false only because the field needs a value.", "hi": "SIPRI सैन्य व्यय को GDP से भाग देकर, कैलेंडर वर्ष। विश्व बैंक यही SIPRI आँकड़े दोबारा प्रकाशित करता है; दोनों अलग रेखाओं में हैं। अर्थव्यवस्था पर बोझ का मोटा माप; SIPRI के अनुसार सैन्य व्यय एक इनपुट है, सैन्य क्षमता या सुरक्षा का माप नहीं। इसमें कोई भी दिशा ''बेहतर'' नहीं है: higher_is_better को केवल इसलिए false रखा गया है क्योंकि इस क्षेत्र में कोई मान देना ज़रूरी है।"}'::jsonb, '% of GDP', 'multiple', false, null, 3, '[0, 5]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('milex_pct_govt', '{"en": "Military expenditure as a share of general government expenditure (SIPRI)", "hi": "सामान्य सरकारी व्यय के हिस्से के रूप में सैन्य व्यय (SIPRI)"}'::jsonb, '{"en": "Military spending, % of govt spending", "hi": "सैन्य व्यय, सरकारी व्यय का %"}'::jsonb, '{"en": "SIPRI military spending divided by general government expenditure (IMF World Economic Outlook), which includes the Centre, states and local bodies, not only the Union budget. Calendar years, from 1988. SIPRI calls military spending an input, not a measure of military capability or security. Neither direction is ''better'': higher_is_better is set to false only because the field needs a value.", "hi": "SIPRI सैन्य व्यय को सामान्य सरकारी व्यय (IMF विश्व आर्थिक परिदृश्य) से भाग देकर, जिसमें केवल केंद्रीय बजट नहीं बल्कि केंद्र, राज्य और स्थानीय निकाय शामिल हैं। कैलेंडर वर्ष, 1988 से। SIPRI के अनुसार सैन्य व्यय एक इनपुट है, सैन्य क्षमता या सुरक्षा का माप नहीं। इसमें कोई भी दिशा ''बेहतर'' नहीं है: higher_is_better को केवल इसलिए false रखा गया है क्योंकि इस क्षेत्र में कोई मान देना ज़रूरी है।"}'::jsonb, '% of government spending', 'multiple', false, null, 4, '[0, 16]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('arms_imports_tiv', '{"en": "Volume of major conventional weapons delivered to India, in SIPRI trend-indicator values", "hi": "भारत को दिए गए प्रमुख पारंपरिक हथियारों की मात्रा, SIPRI ट्रेंड-इंडिकेटर वैल्यू में"}'::jsonb, '{"en": "Arms imports (SIPRI TIV)", "hi": "हथियार आयात (SIPRI TIV)"}'::jsonb, '{"en": "Deliveries of major arms (aircraft, ships, armoured vehicles, missiles and similar) by year of delivery. TIV is not money: SIPRI''s trend-indicator value measures the volume of military resources transferred, based on production costs of a core set of weapons, and SIPRI says it must not be compared with prices, budgets or GDP. Use it for trends and shares. Neither direction is ''better'': higher_is_better is set to false only because the field needs a value.", "hi": "प्रमुख हथियारों (विमान, जहाज़, बख़्तरबंद वाहन, मिसाइल आदि) की आपूर्ति, आपूर्ति वर्ष के अनुसार। TIV पैसा नहीं है: SIPRI का ट्रेंड-इंडिकेटर वैल्यू हथियारों के एक मुख्य समूह की उत्पादन लागत के आधार पर हस्तांतरित सैन्य संसाधनों की मात्रा मापता है, और SIPRI कहता है कि इसकी तुलना कीमतों, बजट या GDP से नहीं करनी चाहिए। इसे रुझानों और हिस्सों के लिए इस्तेमाल करें। इसमें कोई भी दिशा ''बेहतर'' नहीं है: higher_is_better को केवल इसलिए false रखा गया है क्योंकि इस क्षेत्र में कोई मान देना ज़रूरी है।"}'::jsonb, 'million SIPRI TIV (not money)', 'multiple', false, null, 5, '[0, 6000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('arms_exports_tiv', '{"en": "Volume of major conventional weapons delivered by India to other countries, in SIPRI trend-indicator values", "hi": "भारत द्वारा अन्य देशों को दिए गए प्रमुख पारंपरिक हथियारों की मात्रा, SIPRI ट्रेंड-इंडिकेटर वैल्यू में"}'::jsonb, '{"en": "Arms exports (SIPRI TIV)", "hi": "हथियार निर्यात (SIPRI TIV)"}'::jsonb, '{"en": "India''s deliveries of major arms abroad by year. TIV is not money and is not comparable with the rupee export figures of the Department of Defence Production, which also count parts, components and services. Years in which SIPRI identified no deliveries are blank. Neither direction is ''better'': higher_is_better is set to false only because the field needs a value.", "hi": "विदेश को भारत की प्रमुख हथियारों की आपूर्ति, वर्ष के अनुसार। TIV पैसा नहीं है और रक्षा उत्पादन विभाग के रुपये वाले निर्यात आँकड़ों से तुलनीय नहीं है, जिनमें पुर्ज़े, घटक और सेवाएँ भी गिनी जाती हैं। जिन वर्षों में SIPRI को कोई आपूर्ति नहीं मिली, वे ख़ाली हैं। इसमें कोई भी दिशा ''बेहतर'' नहीं है: higher_is_better को केवल इसलिए false रखा गया है क्योंकि इस क्षेत्र में कोई मान देना ज़रूरी है।"}'::jsonb, 'million SIPRI TIV (not money)', 'multiple', false, null, 6, '[0, 200]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('armed_forces_personnel', '{"en": "Active armed forces personnel, including paramilitary forces (IISS via the World Bank)", "hi": "सक्रिय सशस्त्र बल कार्मिक, अर्धसैनिक बलों सहित (IISS, विश्व बैंक के माध्यम से)"}'::jsonb, '{"en": "Armed forces personnel", "hi": "सशस्त्र बल कार्मिक"}'::jsonb, '{"en": "Active-duty military personnel plus paramilitary forces that IISS judges could support or replace regular forces; reservists are excluded. From IISS The Military Balance, partly IISS estimates. The series rises from 1.27 million (1994) to 2.15 million (1995); the World Bank metadata does not explain the step, so compare across it with care. Ends in 2020 in the World Bank data. Neither direction is ''better'': higher_is_better is set to false only because the field needs a value.", "hi": "सक्रिय सैन्य कार्मिक और वे अर्धसैनिक बल जिन्हें IISS नियमित बलों की सहायता या उनकी जगह लेने योग्य मानता है; रिज़र्व शामिल नहीं। IISS द मिलिट्री बैलेंस से, आंशिक रूप से IISS के अनुमान। यह शृंखला 12.7 लाख (1994) से 21.5 लाख (1995) तक बढ़ती है; विश्व बैंक का मेटाडेटा इस उछाल की व्याख्या नहीं करता, इसलिए इसके आर-पार तुलना सावधानी से करें। विश्व बैंक के आँकड़े 2020 पर समाप्त होते हैं। इसमें कोई भी दिशा ''बेहतर'' नहीं है: higher_is_better को केवल इसलिए false रखा गया है क्योंकि इस क्षेत्र में कोई मान देना ज़रूरी है।"}'::jsonb, 'persons', 'multiple', false, null, 7, '[0, 3500000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('def_budget_capital_cr', '{"en": "Capital Outlay on Defence Services: Union Budget demand of the Ministry of Defence", "hi": "रक्षा सेवाओं पर पूंजी परिव्यय: रक्षा मंत्रालय की केंद्रीय बजट मांग"}'::jsonb, '{"en": "Defence capital outlay", "hi": "रक्षा पूंजी परिव्यय"}'::jsonb, '{"en": "Capital spending of the armed forces, the ''Capital Outlay on Defence Services'' demand. Its heads include land, aircraft and aero-engines, heavy and medium vehicles, other equipment, naval fleet and dockyards, construction works, and investment in defence public enterprises (2026-27 document). Union Budget, Notes on Demands for Grants, net of recoveries. Budget Estimates (the year''s allocation, from that year''s budget) and Actuals (spent, printed two years later) are separate lines; Revised Estimates are not shown. Neither direction is ''better'': higher_is_better is set to false only because the field needs a value.", "hi": "सशस्त्र बलों का पूंजीगत व्यय, ''रक्षा सेवाओं पर पूंजी परिव्यय'' मांग। इसके शीर्षों में भूमि, विमान और एयरो-इंजन, भारी और मध्यम वाहन, अन्य उपकरण, नौसैनिक बेड़ा और गोदी, निर्माण कार्य और रक्षा सार्वजनिक उपक्रमों में निवेश शामिल हैं (2026-27 दस्तावेज़)। केंद्रीय बजट, अनुदान मांगों पर टिप्पणियाँ, वसूलियों को घटाकर। बजट अनुमान (उसी वर्ष के बजट में आवंटन) और वास्तविक (खर्च, दो वर्ष बाद छपा) अलग-अलग रेखाएँ हैं; संशोधित अनुमान नहीं दिखाए गए। इसमें कोई भी दिशा ''बेहतर'' नहीं है: higher_is_better को केवल इसलिए false रखा गया है क्योंकि इस क्षेत्र में कोई मान देना ज़रूरी है।"}'::jsonb, '₹ crore (current prices)', 'multiple', false, null, 8, '[0, 250000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('def_budget_revenue_cr', '{"en": "Defence Services (Revenue): Union Budget demand of the Ministry of Defence", "hi": "रक्षा सेवाएँ (राजस्व): रक्षा मंत्रालय की केंद्रीय बजट मांग"}'::jsonb, '{"en": "Defence revenue spending", "hi": "रक्षा राजस्व व्यय"}'::jsonb, '{"en": "Day-to-day spending of the armed forces (pay and allowances, stores, transportation, works and other running costs, as in the demand''s heads), the ''Defence Services (Revenue)'' demand. Excludes pensions and capital outlay. This single demand starts in the 2016-17 documents, which also recast 2014-15 Actuals and the 2015-16 Budget Estimate; earlier years were split over five demands and are not added up here. Union Budget, Notes on Demands for Grants, net of recoveries. Budget Estimates (the year''s allocation, from that year''s budget) and Actuals (spent, printed two years later) are separate lines; Revised Estimates are not shown. Neither direction is ''better'': higher_is_better is set to false only because the field needs a value.", "hi": "सशस्त्र बलों का दैनिक व्यय (वेतन और भत्ते, भंडार, परिवहन, निर्माण कार्य, रखरखाव), ''रक्षा सेवाएँ (राजस्व)'' मांग। इसमें पेंशन और पूंजी परिव्यय शामिल नहीं। यह एकल मांग 2016-17 के दस्तावेज़ों से शुरू होती है, जिनमें 2014-15 के वास्तविक और 2015-16 के बजट अनुमान भी नए ढाँचे में दिए गए; पहले के वर्ष पाँच मांगों में बँटे थे और यहाँ जोड़े नहीं गए। केंद्रीय बजट, अनुदान मांगों पर टिप्पणियाँ, वसूलियों को घटाकर। बजट अनुमान (उसी वर्ष के बजट में आवंटन) और वास्तविक (खर्च, दो वर्ष बाद छपा) अलग-अलग रेखाएँ हैं; संशोधित अनुमान नहीं दिखाए गए। इसमें कोई भी दिशा ''बेहतर'' नहीं है: higher_is_better को केवल इसलिए false रखा गया है क्योंकि इस क्षेत्र में कोई मान देना ज़रूरी है।"}'::jsonb, '₹ crore (current prices)', 'multiple', false, null, 9, '[0, 400000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('def_pensions_cr', '{"en": "Defence Pensions: Union Budget demand of the Ministry of Defence", "hi": "रक्षा पेंशन: रक्षा मंत्रालय की केंद्रीय बजट मांग"}'::jsonb, '{"en": "Defence pensions", "hi": "रक्षा पेंशन"}'::jsonb, '{"en": "Pensions and other retirement benefits paid under the ''Defence Pensions'' demand. Union Budget, Notes on Demands for Grants, net of recoveries. Budget Estimates (the year''s allocation, from that year''s budget) and Actuals (spent, printed two years later) are separate lines; Revised Estimates are not shown. Neither direction is ''better'': higher_is_better is set to false only because the field needs a value.", "hi": "''रक्षा पेंशन'' मांग के तहत दी गई पेंशन और अन्य सेवानिवृत्ति लाभ। केंद्रीय बजट, अनुदान मांगों पर टिप्पणियाँ, वसूलियों को घटाकर। बजट अनुमान (उसी वर्ष के बजट में आवंटन) और वास्तविक (खर्च, दो वर्ष बाद छपा) अलग-अलग रेखाएँ हैं; संशोधित अनुमान नहीं दिखाए गए। इसमें कोई भी दिशा ''बेहतर'' नहीं है: higher_is_better को केवल इसलिए false रखा गया है क्योंकि इस क्षेत्र में कोई मान देना ज़रूरी है।"}'::jsonb, '₹ crore (current prices)', 'multiple', false, null, 10, '[0, 200000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('def_production_cr', '{"en": "Value of defence production in India (Department of Defence Production)", "hi": "भारत में रक्षा उत्पादन का मूल्य (रक्षा उत्पादन विभाग)"}'::jsonb, '{"en": "Defence production", "hi": "रक्षा उत्पादन"}'::jsonb, '{"en": "Value of production reported by Defence PSUs, the companies formed from the Ordnance Factory Board, other PSUs and private firms making defence items, by financial year, in that year''s rupees (not adjusted for inflation). Self-reported and revised; the latest year can be provisional. A 2014-15 figure from a PIB release is a separate line. Neither direction is ''better'': higher_is_better is set to false only because the field needs a value.", "hi": "रक्षा सार्वजनिक उपक्रमों, आयुध निर्माणी बोर्ड से बनी कंपनियों, अन्य सार्वजनिक उपक्रमों और रक्षा सामान बनाने वाली निजी कंपनियों द्वारा बताया गया उत्पादन मूल्य, वित्त वर्ष के अनुसार, उस वर्ष के रुपयों में (मुद्रास्फीति समायोजित नहीं)। स्वयं बताए गए और संशोधित आँकड़े; नवीनतम वर्ष अनंतिम हो सकता है। PIB विज्ञप्ति से 2014-15 का आँकड़ा अलग रेखा है। इसमें कोई भी दिशा ''बेहतर'' नहीं है: higher_is_better को केवल इसलिए false रखा गया है क्योंकि इस क्षेत्र में कोई मान देना ज़रूरी है।"}'::jsonb, '₹ crore (current prices)', 'multiple', false, null, 11, '[0, 200000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('def_exports_cr', '{"en": "Defence exports in rupees crore (Department of Defence Production)", "hi": "करोड़ रुपये में रक्षा निर्यात (रक्षा उत्पादन विभाग)"}'::jsonb, '{"en": "Defence exports (₹)", "hi": "रक्षा निर्यात (₹)"}'::jsonb, '{"en": "Exports by Defence PSUs and by private firms under DDP export authorisations, including parts, components and services, by financial year, in that year''s rupees. A money value, unlike SIPRI''s TIV, and not comparable with it. An earlier Parliament table (2022) and a PIB figure for 2013-14 are separate lines. Neither direction is ''better'': higher_is_better is set to false only because the field needs a value.", "hi": "रक्षा सार्वजनिक उपक्रमों और DDP निर्यात प्राधिकरणों के तहत निजी कंपनियों का निर्यात, पुर्ज़ों, घटकों और सेवाओं सहित, वित्त वर्ष के अनुसार, उस वर्ष के रुपयों में। यह पैसे का मूल्य है, SIPRI के TIV जैसा नहीं, और उससे तुलनीय नहीं। संसद की पहले की तालिका (2022) और 2013-14 का PIB आँकड़ा अलग रेखाएँ हैं। इसमें कोई भी दिशा ''बेहतर'' नहीं है: higher_is_better को केवल इसलिए false रखा गया है क्योंकि इस क्षेत्र में कोई मान देना ज़रूरी है।"}'::jsonb, '₹ crore (current prices)', 'multiple', false, null, 12, '[0, 40000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('jobs_agri_share', '{"en": "Share of workers whose main or subsidiary work is in agriculture, forestry and fishing", "hi": "कृषि, वानिकी और मत्स्य पालन में मुख्य या सहायक काम करने वाले श्रमिकों का हिस्सा"}'::jsonb, '{"en": "Jobs in farming", "hi": "खेती में रोज़गार"}'::jsonb, '{"en": "Per cent of usually working persons (principal + subsidiary status) whose industry of work is NIC-2008 section A. PLFS survey estimate; July-June agricultural years.", "hi": "सामान्य रूप से काम करने वाले व्यक्तियों (मुख्य + सहायक स्थिति) का प्रतिशत जिनका काम NIC-2008 खंड A में है। PLFS सर्वेक्षण अनुमान; जुलाई-जून कृषि वर्ष।"}'::jsonb, '%', 'multiple', none, null, 1, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('jobs_industry_share', '{"en": "Share of workers in industry: mining, manufacturing, electricity, gas, water and construction", "hi": "उद्योग में श्रमिकों का हिस्सा: खनन, विनिर्माण, बिजली, गैस, पानी और निर्माण कार्य"}'::jsonb, '{"en": "Jobs in industry", "hi": "उद्योग में रोज़गार"}'::jsonb, '{"en": "Sum of NIC-2008 sections B to F as printed in the PLFS state tables (calculated here; the report gives sections, not this total). Construction is a large part of it.", "hi": "PLFS राज्य तालिकाओं में छपे NIC-2008 खंड B से F का योग (यहाँ परिकलित; रिपोर्ट में केवल खंड दिए हैं)। इसमें निर्माण कार्य का बड़ा हिस्सा है।"}'::jsonb, '%', 'multiple', none, null, 2, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('jobs_services_share', '{"en": "Share of workers in services: trade, transport, hotels, finance, public administration, education, health and other services", "hi": "सेवाओं में श्रमिकों का हिस्सा: व्यापार, परिवहन, होटल, वित्त, लोक प्रशासन, शिक्षा, स्वास्थ्य और अन्य सेवाएँ"}'::jsonb, '{"en": "Jobs in services", "hi": "सेवाओं में रोज़गार"}'::jsonb, '{"en": "Sum of NIC-2008 sections G to U as printed in the PLFS state tables (calculated here).", "hi": "PLFS राज्य तालिकाओं में छपे NIC-2008 खंड G से U का योग (यहाँ परिकलित)।"}'::jsonb, '%', 'multiple', none, null, 3, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('jobs_manufacturing_share', '{"en": "Share of workers in manufacturing", "hi": "विनिर्माण में काम करने वाले श्रमिकों का हिस्सा"}'::jsonb, '{"en": "Jobs in manufacturing", "hi": "विनिर्माण में रोज़गार"}'::jsonb, '{"en": "Per cent of usually working persons (ps+ss) in NIC-2008 section C (manufacturing), formal and informal. PLFS survey estimate.", "hi": "सामान्य रूप से काम करने वाले व्यक्तियों (ps+ss) का प्रतिशत जो NIC-2008 खंड C (विनिर्माण) में हैं, औपचारिक और अनौपचारिक दोनों। PLFS सर्वेक्षण अनुमान।"}'::jsonb, '%', 'multiple', none, null, 4, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('jobs_construction_share', '{"en": "Share of workers in construction", "hi": "निर्माण कार्य में लगे श्रमिकों का हिस्सा"}'::jsonb, '{"en": "Jobs in construction", "hi": "निर्माण कार्य में रोज़गार"}'::jsonb, '{"en": "Per cent of usually working persons (ps+ss) in NIC-2008 section F (construction). PLFS survey estimate.", "hi": "सामान्य रूप से काम करने वाले व्यक्तियों (ps+ss) का प्रतिशत जो NIC-2008 खंड F (निर्माण कार्य) में हैं। PLFS सर्वेक्षण अनुमान।"}'::jsonb, '%', 'multiple', none, null, 5, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('unemployment_rate', '{"en": "Unemployment rate, usual status (ps+ss), age 15 and above", "hi": "बेरोज़गारी दर, सामान्य स्थिति (ps+ss), 15 वर्ष और अधिक आयु"}'::jsonb, '{"en": "Unemployment rate", "hi": "बेरोज़गारी दर"}'::jsonb, '{"en": "Unemployed persons as a per cent of the labour force (those working or seeking work), age 15+, usual status. Someone who did any subsidiary work during the year counts as employed, so this rate is low by design.", "hi": "श्रम बल (काम करने वाले या काम खोजने वाले) में बेरोज़गार व्यक्तियों का प्रतिशत, 15+ आयु, सामान्य स्थिति। वर्ष में कोई भी सहायक काम करने वाला रोज़गार में गिना जाता है, इसलिए यह दर स्वभावतः कम रहती है।"}'::jsonb, '%', 'multiple', false, null, 6, '[0, 40]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('wpr', '{"en": "Worker population ratio, usual status (ps+ss), age 15 and above", "hi": "श्रमिक जनसंख्या अनुपात, सामान्य स्थिति (ps+ss), 15 वर्ष और अधिक आयु"}'::jsonb, '{"en": "Worker population ratio", "hi": "श्रमिक जनसंख्या अनुपात"}'::jsonb, '{"en": "Workers as a per cent of all persons aged 15+. Includes unpaid helpers in household enterprises.", "hi": "15+ आयु के सभी व्यक्तियों में श्रमिकों का प्रतिशत। इसमें घरेलू उद्यमों में बिना वेतन के सहायक भी शामिल हैं।"}'::jsonb, '%', 'multiple', true, null, 7, '[0, 80]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('factories', '{"en": "Number of factories covered by the Annual Survey of Industries", "hi": "उद्योगों के वार्षिक सर्वेक्षण में शामिल कारखानों की संख्या"}'::jsonb, '{"en": "Factories", "hi": "कारखाने"}'::jsonb, '{"en": "Registered factories (Factories Act; mainly 10+ workers with power or 20+ without) counted by ASI. Excludes small unregistered units.", "hi": "ASI द्वारा गिने गए पंजीकृत कारखाने (कारखाना अधिनियम; मुख्यतः बिजली के साथ 10+ या बिना बिजली 20+ श्रमिक)। छोटी अपंजीकृत इकाइयाँ शामिल नहीं।"}'::jsonb, 'number', 'multiple', true, null, 8, '[0, 300000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('factory_workers', '{"en": "Number of workers in factories (Annual Survey of Industries)", "hi": "कारखानों में श्रमिकों की संख्या (उद्योगों का वार्षिक सर्वेक्षण)"}'::jsonb, '{"en": "Factory workers", "hi": "कारखाना श्रमिक"}'::jsonb, '{"en": "Workers directly or through contractors engaged in manufacturing in ASI factories; excludes supervisory and managerial staff (counted under employees).", "hi": "ASI कारखानों में विनिर्माण में सीधे या ठेकेदार के माध्यम से लगे श्रमिक; पर्यवेक्षी और प्रबंधकीय कर्मचारी (कर्मचारियों में गिने जाते हैं) शामिल नहीं।"}'::jsonb, 'number', 'multiple', true, null, 9, '[0, 20000000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('factory_gva_inr_crore', '{"en": "Gross value added by factories (ASI), current prices", "hi": "कारखानों द्वारा सकल मूल्य वर्धन (ASI), चालू मूल्य"}'::jsonb, '{"en": "Factory value added", "hi": "कारखानों का मूल्य वर्धन"}'::jsonb, '{"en": "Value of output minus inputs of ASI factories, before depreciation, in that year''s rupees (not adjusted for inflation).", "hi": "ASI कारखानों के उत्पादन मूल्य में से इनपुट घटाकर, मूल्यह्रास से पहले, उसी वर्ष के रुपयों में (मुद्रास्फीति समायोजित नहीं)।"}'::jsonb, '₹ crore (that year''s prices)', 'multiple', true, null, 10, '[0, 3000000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('trade_exports_usd_bn', '{"en": "India''s merchandise exports, US$ billion, April-March", "hi": "भारत का वस्तु निर्यात, अरब अमेरिकी डॉलर, अप्रैल-मार्च"}'::jsonb, '{"en": "Merchandise exports", "hi": "वस्तु निर्यात"}'::jsonb, '{"en": "Goods exported as recorded by DGCI&S (customs basis), oil and non-oil, in current US dollars. Excludes services exports.", "hi": "DGCI&S द्वारा दर्ज (सीमा शुल्क आधार) निर्यात की गई वस्तुएँ, तेल और गैर-तेल, चालू अमेरिकी डॉलर में। सेवाओं का निर्यात शामिल नहीं।"}'::jsonb, 'US$ billion', 'multiple', true, null, 11, '[0, 500]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('trade_imports_usd_bn', '{"en": "India''s merchandise imports, US$ billion, April-March", "hi": "भारत का वस्तु आयात, अरब अमेरिकी डॉलर, अप्रैल-मार्च"}'::jsonb, '{"en": "Merchandise imports", "hi": "वस्तु आयात"}'::jsonb, '{"en": "Goods imported as recorded by DGCI&S (customs basis), oil and non-oil, in current US dollars. Excludes services imports.", "hi": "DGCI&S द्वारा दर्ज (सीमा शुल्क आधार) आयात की गई वस्तुएँ, तेल और गैर-तेल, चालू अमेरिकी डॉलर में। सेवाओं का आयात शामिल नहीं।"}'::jsonb, 'US$ billion', 'multiple', none, null, 12, '[0, 800]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('gdp_per_capita_current', '{"en": "Gross domestic product per person, current prices", "hi": "प्रति व्यक्ति सकल घरेलू उत्पाद, चालू मूल्य"}'::jsonb, '{"en": "GDP per person (that year''s ₹)", "hi": "प्रति व्यक्ति जीडीपी (उसी वर्ष के ₹)"}'::jsonb, '{"en": "GDP divided by mid-year population, in that year''s rupees. Larger than income per person (NNI per capita) because it still includes depreciation and income paid abroad. Base years 2011-12 and 2022-23 are separate series.", "hi": "मध्य-वर्ष जनसंख्या से विभाजित जीडीपी, उसी वर्ष के रुपयों में। प्रति व्यक्ति आय (प्रति व्यक्ति NNI) से अधिक, क्योंकि इसमें मूल्यह्रास और विदेश को दी गई आय शामिल रहती है। आधार वर्ष 2011-12 और 2022-23 अलग श्रृंखलाएँ हैं।"}'::jsonb, '₹ (that year''s prices)', 'multiple', true, null, 13, '[0, 300000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('gdp_per_capita_constant', '{"en": "Gross domestic product per person at constant prices (2011-12 or 2022-23 prices)", "hi": "स्थिर मूल्यों (2011-12 या 2022-23 के मूल्य) पर प्रति व्यक्ति सकल घरेलू उत्पाद"}'::jsonb, '{"en": "GDP per person (fixed prices)", "hi": "प्रति व्यक्ति जीडीपी (स्थिर मूल्य)"}'::jsonb, '{"en": "Real GDP per person; inflation removed using the base year''s prices. The two base series have different price levels and must not be joined.", "hi": "वास्तविक प्रति व्यक्ति जीडीपी; आधार वर्ष के मूल्यों से मुद्रास्फीति हटाई गई। दोनों आधार श्रृंखलाओं के मूल्य स्तर अलग हैं और इन्हें जोड़ा नहीं जाना चाहिए।"}'::jsonb, '₹ (base-year prices)', 'multiple', true, null, 14, '[0, 300000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('cfc_share_gdp', '{"en": "Consumption of fixed capital (depreciation) as a per cent of GDP, current prices", "hi": "जीडीपी के प्रतिशत के रूप में अचल पूंजी का उपभोग (मूल्यह्रास), चालू मूल्य"}'::jsonb, '{"en": "Depreciation share of GDP", "hi": "जीडीपी में मूल्यह्रास का हिस्सा"}'::jsonb, '{"en": "Wear and tear of buildings, machinery and other fixed assets, as a share of GDP at market prices. Calculated here from the two printed values. This is the main gap between GDP and net national income.", "hi": "भवनों, मशीनरी और अन्य अचल परिसंपत्तियों की टूट-फूट, बाज़ार मूल्य पर जीडीपी के हिस्से के रूप में। यहाँ दो छपे मानों से परिकलित। यही जीडीपी और शुद्ध राष्ट्रीय आय के बीच का मुख्य अंतर है।"}'::jsonb, '%', 'multiple', none, null, 15, '[0, 20]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('cfc_current_inr_crore', '{"en": "Consumption of fixed capital, current prices", "hi": "अचल पूंजी का उपभोग, चालू मूल्य"}'::jsonb, '{"en": "Depreciation (₹ crore)", "hi": "मूल्यह्रास (₹ करोड़)"}'::jsonb, '{"en": "Depreciation of the economy''s fixed assets as estimated in the national accounts, in that year''s rupees.", "hi": "राष्ट्रीय लेखा में अनुमानित अर्थव्यवस्था की अचल परिसंपत्तियों का मूल्यह्रास, उसी वर्ष के रुपयों में।"}'::jsonb, '₹ crore (that year''s prices)', 'multiple', none, null, 16, '[0, 5000000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('nfia_current_inr_crore', '{"en": "Net factor income from abroad (primary income receivable from the rest of the world, net), current prices", "hi": "विदेश से शुद्ध साधन आय (शेष विश्व से प्राप्य प्राथमिक आय, शुद्ध), चालू मूल्य"}'::jsonb, '{"en": "Net income from abroad", "hi": "विदेश से शुद्ध आय"}'::jsonb, '{"en": "Income earned by Indians abroad minus income paid to foreigners (interest, profits, wages). Negative means more goes out than comes in; GNI = GDP + this.", "hi": "विदेश में भारतीयों द्वारा अर्जित आय में से विदेशियों को दी गई आय (ब्याज, लाभ, मज़दूरी) घटाकर। ऋणात्मक का अर्थ है जितनी आय आती है उससे अधिक बाहर जाती है; GNI = GDP + यह।"}'::jsonb, '₹ crore (that year''s prices)', 'multiple', none, null, 17, '[-500000, 400]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('hospital_beds_per_1000', '{"en": "Hospital beds per 1,000 people", "hi": "प्रति 1,000 लोगों पर अस्पताल बिस्तर"}'::jsonb, '{"en": "Hospital beds", "hi": "अस्पताल बिस्तर"}'::jsonb, '{"en": "Inpatient hospital beds, public and private, per 1,000 people (World Bank, from WHO and country data). All-India only: the National Health Profile prints state counts of government hospital beds but not population or a per-person rate, and its coverage changes sharply from year to year. No WHO norm for hospital beds is shown because we found no official WHO document stating one.", "hi": "प्रति 1,000 लोगों पर अस्पतालों में भर्ती के बिस्तर, सरकारी और निजी दोनों (विश्व बैंक, WHO और देश के आंकड़ों से)। केवल अखिल भारत: राष्ट्रीय स्वास्थ्य प्रोफ़ाइल राज्यों के सरकारी अस्पताल बिस्तरों की संख्या छापती है, पर जनसंख्या या प्रति व्यक्ति दर नहीं, और उसका कवरेज साल-दर-साल बहुत बदलता है। अस्पताल बिस्तरों का कोई WHO मानक नहीं दिखाया गया है क्योंकि हमें ऐसा कोई आधिकारिक WHO दस्तावेज़ नहीं मिला।"}'::jsonb, 'beds per 1,000 people', 'multiple', true, null, 101, '[0, 5]'::jsonb, 2, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('doctors_per_10000', '{"en": "Medical doctors (allopathic) per 10,000 people", "hi": "प्रति 10,000 लोगों पर चिकित्सक (एलोपैथिक)"}'::jsonb, '{"en": "Doctors", "hi": "डॉक्टर"}'::jsonb, '{"en": "Modern-medicine (allopathic) doctors per 10,000 people, from the WHO Global Health Observatory. For India WHO uses doctors registered with state medical councils and the National Medical Commission, a cumulative count that includes doctors who have retired, died, emigrated or are registered twice, so it overstates doctors actually working. AYUSH practitioners are excluded. Benchmark: WHO''s Global Strategy on Human Resources for Health: Workforce 2030 (2016, Annex 1) uses an indicative threshold of 44.5 doctors, nurses and midwives together per 10,000 people; it is not a threshold for doctors alone (see health workers).", "hi": "प्रति 10,000 लोगों पर आधुनिक चिकित्सा (एलोपैथिक) डॉक्टर, WHO ग्लोबल हेल्थ ऑब्ज़र्वेटरी से। भारत के लिए WHO राज्य चिकित्सा परिषदों और राष्ट्रीय चिकित्सा आयोग में पंजीकृत डॉक्टरों की संचयी संख्या लेता है, जिसमें सेवानिवृत्त, मृत, विदेश गए या दो बार पंजीकृत डॉक्टर भी शामिल हैं, इसलिए यह वास्तव में काम कर रहे डॉक्टरों से अधिक है। आयुष चिकित्सक शामिल नहीं हैं। मानदंड: WHO की ''Global Strategy on Human Resources for Health: Workforce 2030'' (2016, अनुलग्नक 1) डॉक्टर, नर्स और दाई को मिलाकर प्रति 10,000 लोगों पर 44.5 की सांकेतिक सीमा का उपयोग करती है; यह केवल डॉक्टरों की सीमा नहीं है (स्वास्थ्यकर्मी देखें)।"}'::jsonb, 'doctors per 10,000 people', 'multiple', true, null, 102, '[0, 50]'::jsonb, 2, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('nurses_midwives_per_10000', '{"en": "Nursing and midwifery personnel per 10,000 people", "hi": "प्रति 10,000 लोगों पर नर्सिंग और मिडवाइफरी कर्मी"}'::jsonb, '{"en": "Nurses and midwives", "hi": "नर्स और दाई"}'::jsonb, '{"en": "Nursing and midwifery personnel per 10,000 people, from the WHO Global Health Observatory. Based on registration data, not a count of nurses currently working.", "hi": "प्रति 10,000 लोगों पर नर्सिंग और मिडवाइफरी कर्मी, WHO ग्लोबल हेल्थ ऑब्ज़र्वेटरी से। यह पंजीकरण आंकड़ों पर आधारित है, वर्तमान में काम कर रही नर्सों की गिनती नहीं।"}'::jsonb, 'nurses and midwives per 10,000 people', 'multiple', true, null, 103, '[0, 50]'::jsonb, 2, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('health_workers_per_10000', '{"en": "Doctors, nurses and midwives per 10,000 people", "hi": "प्रति 10,000 लोगों पर डॉक्टर, नर्स और दाई"}'::jsonb, '{"en": "Doctors, nurses and midwives", "hi": "डॉक्टर, नर्स और दाई"}'::jsonb, '{"en": "Medical doctors plus nursing and midwifery personnel per 10,000 people: the sum of WHO''s two published densities for the same year, added by Tathya. WHO benchmark: 44.5 doctors, nurses and midwives per 10,000 people, the indicative SDG index threshold in WHO''s Global Strategy on Human Resources for Health: Workforce 2030 (2016, Annex 1: 4.45 per 1,000). WHO uses it to estimate workforce needs; it is not a legal norm. Both inputs are registration counts and overstate the active workforce.", "hi": "प्रति 10,000 लोगों पर चिकित्सक और नर्सिंग-मिडवाइफरी कर्मी: उसी वर्ष के WHO के दो प्रकाशित घनत्वों का योग, जिसे Tathya ने जोड़ा है। WHO मानदंड: प्रति 10,000 लोगों पर 44.5 डॉक्टर, नर्स और दाई, जो WHO की ''Global Strategy on Human Resources for Health: Workforce 2030'' (2016, अनुलग्नक 1: प्रति 1,000 पर 4.45) में SDG सूचकांक की सांकेतिक सीमा है। WHO इसका उपयोग कार्यबल की ज़रूरत के अनुमान के लिए करता है; यह कानूनी मानक नहीं है। दोनों आंकड़े पंजीकरण पर आधारित हैं और सक्रिय कार्यबल से अधिक हैं।"}'::jsonb, 'doctors, nurses and midwives per 10,000 people', 'multiple', true, null, 104, '[0, 60]'::jsonb, 2, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('people_per_doctor_mohfw', '{"en": "Doctor-population ratio as stated by the Health Ministry (people per doctor)", "hi": "स्वास्थ्य मंत्रालय द्वारा बताया गया डॉक्टर-जनसंख्या अनुपात (प्रति डॉक्टर लोग)"}'::jsonb, '{"en": "People per doctor (govt estimate)", "hi": "प्रति डॉक्टर लोग (सरकारी अनुमान)"}'::jsonb, '{"en": "The ''1:N'' figure the Ministry of Health gives in Parliament: people per doctor, counting registered allopathic doctors and registered AYUSH practitioners and assuming 80% of them are available. It is an estimate, not a count of working doctors, and it is not comparable with WHO''s allopathic-only density. Answers call it better than a ''WHO standard of 1:1000''; we found no WHO document stating such a standard.", "hi": "संसद में स्वास्थ्य मंत्रालय द्वारा दिया गया ''1:N'' आंकड़ा: प्रति डॉक्टर लोग, जिसमें पंजीकृत एलोपैथिक डॉक्टर और पंजीकृत आयुष चिकित्सक गिने जाते हैं और माना जाता है कि उनमें से 80% उपलब्ध हैं। यह अनुमान है, काम कर रहे डॉक्टरों की गिनती नहीं, और WHO के केवल-एलोपैथिक घनत्व से तुलनीय नहीं है। उत्तरों में इसे ''WHO मानक 1:1000'' से बेहतर बताया गया है; हमें ऐसा मानक बताने वाला कोई WHO दस्तावेज़ नहीं मिला।"}'::jsonb, 'people per doctor', 'multiple', false, null, 105, '[0, 1500]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('med_colleges', '{"en": "Number of medical colleges teaching MBBS (government and private)", "hi": "एमबीबीएस पढ़ाने वाले मेडिकल कॉलेजों की संख्या (सरकारी और निजी)"}'::jsonb, '{"en": "Medical colleges (MBBS)", "hi": "मेडिकल कॉलेज (एमबीबीएस)"}'::jsonb, '{"en": "All colleges permitted by the National Medical Commission to admit MBBS students in that academic year, as reported by MoHFW/NMC. Some sources include AIIMS and other national institutes and some do not; such changes are marked as breaks.", "hi": "उस शैक्षणिक वर्ष में राष्ट्रीय आयुर्विज्ञान आयोग द्वारा एमबीबीएस में प्रवेश की अनुमति प्राप्त सभी कॉलेज, जैसा स्वास्थ्य मंत्रालय/एनएमसी ने बताया। कुछ स्रोतों में एम्स और अन्य राष्ट्रीय संस्थान शामिल हैं और कुछ में नहीं; ऐसे बदलाव विराम के रूप में चिह्नित हैं।"}'::jsonb, 'colleges', 'multiple', true, null, 106, '[0, 900]'::jsonb, 0, '[0, 100]'::jsonb) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('med_colleges_govt', '{"en": "Number of government medical colleges teaching MBBS", "hi": "एमबीबीएस पढ़ाने वाले सरकारी मेडिकल कॉलेजों की संख्या"}'::jsonb, '{"en": "Government medical colleges", "hi": "सरकारी मेडिकल कॉलेज"}'::jsonb, '{"en": "Medical colleges run by the central or state government (including ESIC and municipal colleges) that admit MBBS students. Whether AIIMS and other national institutes are counted depends on the source; see the note on each value.", "hi": "केंद्र या राज्य सरकार द्वारा संचालित (ईएसआईसी और नगर निगम कॉलेजों सहित) एमबीबीएस में प्रवेश देने वाले मेडिकल कॉलेज। एम्स और अन्य राष्ट्रीय संस्थान गिने गए हैं या नहीं, यह स्रोत पर निर्भर है; हर मान का नोट देखें।"}'::jsonb, 'colleges', 'multiple', true, null, 107, '[0, 500]'::jsonb, 0, '[0, 60]'::jsonb) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('med_colleges_private', '{"en": "Number of private medical colleges teaching MBBS (incl. trust, society and deemed-university colleges)", "hi": "एमबीबीएस पढ़ाने वाले निजी मेडिकल कॉलेजों की संख्या (ट्रस्ट, सोसाइटी और डीम्ड विश्वविद्यालय कॉलेज सहित)"}'::jsonb, '{"en": "Private medical colleges", "hi": "निजी मेडिकल कॉलेज"}'::jsonb, '{"en": "Medical colleges not run by government: private, trust and society colleges and deemed universities, combined as the source prints them (\"Pvt.\", \"Pvt., Trust & Society\" or \"Private\").", "hi": "सरकार द्वारा संचालित नहीं होने वाले मेडिकल कॉलेज: निजी, ट्रस्ट और सोसाइटी कॉलेज तथा डीम्ड विश्वविद्यालय, जैसा स्रोत इन्हें एक साथ छापता है (\"Pvt.\", \"Pvt., Trust & Society\" या \"Private\")।"}'::jsonb, 'colleges', 'multiple', true, null, 108, '[0, 500]'::jsonb, 0, '[0, 60]'::jsonb) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('mbbs_seats', '{"en": "Total MBBS seats (annual admission capacity) in medical colleges", "hi": "मेडिकल कॉलेजों में कुल एमबीबीएस सीटें (वार्षिक प्रवेश क्षमता)"}'::jsonb, '{"en": "MBBS seats", "hi": "एमबीबीएस सीटें"}'::jsonb, '{"en": "Number of MBBS students the medical colleges in the state are permitted to admit each year (government plus private). It is capacity, not the number actually admitted.", "hi": "राज्य के मेडिकल कॉलेजों को हर वर्ष जितने एमबीबीएस छात्र प्रवेश देने की अनुमति है (सरकारी और निजी मिलाकर)। यह क्षमता है, वास्तव में प्रवेश पाए छात्रों की संख्या नहीं।"}'::jsonb, 'seats', 'multiple', true, null, 109, '[0, 150000]'::jsonb, 0, '[0, 16000]'::jsonb) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('schools', '{"en": "Number of schools", "hi": "विद्यालयों की संख्या"}'::jsonb, '{"en": "Schools", "hi": "विद्यालय"}'::jsonb, '{"en": "Total number of schools of all managements (government, government-aided, private unaided recognised and others), from primary to higher secondary, as counted by UDISE+.", "hi": "यूडाइस+ द्वारा गिने गए सभी प्रबंधनों (सरकारी, सरकारी सहायता प्राप्त, मान्यता प्राप्त निजी गैर-सहायता प्राप्त और अन्य) के कुल विद्यालय, प्राथमिक से उच्चतर माध्यमिक तक।"}'::jsonb, 'schools', 'multiple', true, null, 110, '[0, 1600000]'::jsonb, 0, '[0, 300000]'::jsonb) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('ger_secondary', '{"en": "Gross enrolment ratio, secondary (classes IX-X)", "hi": "सकल नामांकन अनुपात, माध्यमिक (कक्षा 9-10)"}'::jsonb, '{"en": "Secondary GER", "hi": "माध्यमिक GER"}'::jsonb, '{"en": "Students enrolled in classes IX-X, of any age, as a percentage of the projected population aged 14-15. It can exceed 100 when over- or under-age children are enrolled.", "hi": "कक्षा 9-10 में नामांकित किसी भी आयु के छात्र, 14-15 वर्ष की अनुमानित जनसंख्या के प्रतिशत के रूप में। अधिक या कम आयु के बच्चों के नामांकन से यह 100 से ऊपर जा सकता है।"}'::jsonb, '%', 'multiple', true, null, 111, '[0, 130]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('ptr_secondary', '{"en": "Pupil-teacher ratio, secondary (classes IX-X)", "hi": "छात्र-शिक्षक अनुपात, माध्यमिक (कक्षा 9-10)"}'::jsonb, '{"en": "Secondary PTR", "hi": "माध्यमिक PTR"}'::jsonb, '{"en": "Students enrolled in classes IX-X per teacher teaching those classes. Lower means more teachers per student. Most UDISE+ reports print it as a whole number (2019-20: one decimal).", "hi": "कक्षा 9-10 में नामांकित छात्र प्रति शिक्षक (उन कक्षाओं को पढ़ाने वाले)। कम अंक का अर्थ है प्रति छात्र अधिक शिक्षक। अधिकांश यूडाइस+ रिपोर्टों में यह पूर्णांक में छपा है (2019-20: एक दशमलव)।"}'::jsonb, 'pupils per teacher', 'multiple', false, null, 112, '[0, 60]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('colleges_per_lakh', '{"en": "Colleges per lakh population aged 18-23", "hi": "18-23 वर्ष की प्रति लाख आबादी पर कॉलेज"}'::jsonb, '{"en": "College density", "hi": "कॉलेज घनत्व"}'::jsonb, '{"en": "Number of colleges per 1,00,000 people in the eligible age group 18-23, from the All India Survey on Higher Education (AISHE). The 18-23 population base changed from 2001-census to 2011-census projections with the 2020-21 report, marked as a break.", "hi": "उच्च शिक्षा पर अखिल भारतीय सर्वेक्षण (AISHE) के अनुसार 18-23 वर्ष की पात्र आयु वर्ग की प्रति 1,00,000 आबादी पर कॉलेजों की संख्या। 2020-21 की रिपोर्ट से 18-23 आबादी का आधार 2001 जनगणना के अनुमानों से बदलकर 2011 जनगणना के अनुमान हो गया, जिसे विराम के रूप में दिखाया गया है।"}'::jsonb, 'colleges per lakh people aged 18-23', 'multiple', true, null, 113, '[0, 100]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('ger_higher', '{"en": "Gross enrolment ratio in higher education (18-23)", "hi": "उच्च शिक्षा में सकल नामांकन अनुपात (18-23 वर्ष)"}'::jsonb, '{"en": "Higher-education GER", "hi": "उच्च शिक्षा GER"}'::jsonb, '{"en": "Total enrolment in higher education, regardless of age, as a percentage of the population aged 18-23 (AISHE). GER from the 2020-21 report onward, and AISHE''s revised time series, use Census-2011-based population projections; earlier annual reports used 2001-census projections and printed higher values.", "hi": "उच्च शिक्षा में कुल नामांकन (आयु से परे) को 18-23 वर्ष की आबादी के प्रतिशत के रूप में (AISHE)। 2020-21 की रिपोर्ट से और AISHE की संशोधित समय-श्रृंखला में 2011 जनगणना आधारित जनसंख्या अनुमान उपयोग हुए हैं; पहले की वार्षिक रिपोर्टों में 2001 जनगणना के अनुमान थे और मान अधिक छपे थे।"}'::jsonb, '%', 'multiple', true, null, 114, '[0, 100]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('universities', '{"en": "Number of universities", "hi": "विश्वविद्यालयों की संख्या"}'::jsonb, '{"en": "Universities", "hi": "विश्वविद्यालय"}'::jsonb, '{"en": "Universities and university-level institutions (central, state public, state private, deemed, institutes of national importance and others) covered by the All India Survey on Higher Education in that year.", "hi": "उस वर्ष उच्च शिक्षा पर अखिल भारतीय सर्वेक्षण में शामिल विश्वविद्यालय और विश्वविद्यालय-स्तरीय संस्थान (केंद्रीय, राज्य सार्वजनिक, राज्य निजी, डीम्ड, राष्ट्रीय महत्व के संस्थान आदि)।"}'::jsonb, 'universities', 'multiple', true, null, 115, '[0, 1400]'::jsonb, 0, '[0, 120]'::jsonb) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('nirf_top100', '{"en": "Number of the state''s institutions in the NIRF Overall ranking top 100", "hi": "NIRF समग्र रैंकिंग के शीर्ष 100 में राज्य के संस्थानों की संख्या"}'::jsonb, '{"en": "Institutions in NIRF top 100", "hi": "NIRF शीर्ष 100 में संस्थान"}'::jsonb, '{"en": "How many of the 100 best-ranked higher education institutions in the Ministry of Education''s National Institutional Ranking Framework (Overall category) are located in the state. Ranking is by NIRF''s scores for teaching, research, graduation outcomes, outreach and perception; only institutions that apply are ranked.", "hi": "शिक्षा मंत्रालय के राष्ट्रीय संस्थागत रैंकिंग फ्रेमवर्क (समग्र श्रेणी) में सर्वश्रेष्ठ 100 उच्च शिक्षा संस्थानों में से कितने उस राज्य में हैं। रैंकिंग शिक्षण, अनुसंधान, स्नातक परिणाम, पहुँच और धारणा के NIRF अंकों पर आधारित है; केवल आवेदन करने वाले संस्थान रैंक किए जाते हैं।"}'::jsonb, 'institutions', 'multiple', true, null, 116, '[0, 101]'::jsonb, 0, '[0, 25]'::jsonb) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('nh_length_km', '{"en": "Length of National Highways (km)", "hi": "राष्ट्रीय राजमार्गों की लंबाई (किमी)"}'::jsonb, '{"en": "National Highways", "hi": "राष्ट्रीय राजमार्ग"}'::jsonb, '{"en": "Total length of roads notified as National Highways, as at 31 March (RBI table: end-December for 2022-24). Rises both through construction and when existing state roads are declared NHs, so a jump is not the same as new road built.", "hi": "राष्ट्रीय राजमार्ग घोषित सड़कों की कुल लंबाई, 31 मार्च की स्थिति में (RBI तालिका में 2022-24 के लिए दिसंबर अंत)। यह निर्माण से भी बढ़ती है और तब भी जब मौजूदा राज्य सड़कों को राष्ट्रीय राजमार्ग घोषित किया जाता है, इसलिए अचानक उछाल का मतलब नई सड़क बनना नहीं है।"}'::jsonb, 'km', 'multiple', true, '"Large one-year jumps (e.g. 2016 to 2017) are flagged as breaks; the source does not say whether they are new roads or reclassified ones."'::jsonb, 1, '[0, 160000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('road_length_km', '{"en": "Total length of all roads (km)", "hi": "सभी सड़कों की कुल लंबाई (किमी)"}'::jsonb, '{"en": "Total road length", "hi": "कुल सड़क लंबाई"}'::jsonb, '{"en": "All categories of road (national and state highways, district, rural, urban and project roads), as at 31 March. Includes unsurfaced roads. MoRTH and RBI totals differ in coverage, so they are kept as separate series.", "hi": "सभी श्रेणियों की सड़कें (राष्ट्रीय और राज्य राजमार्ग, जिला, ग्रामीण, शहरी और परियोजना सड़कें), 31 मार्च की स्थिति में। कच्ची सड़कें भी शामिल। MoRTH और RBI के कुल योग का दायरा अलग है, इसलिए दोनों अलग शृंखलाएँ हैं।"}'::jsonb, 'km', 'multiple', true, null, 2, '[0, 7000000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('rail_route_km', '{"en": "Railway route length (route km)", "hi": "रेल मार्ग की लंबाई (मार्ग किमी)"}'::jsonb, '{"en": "Railway route length", "hi": "रेल मार्ग लंबाई"}'::jsonb, '{"en": "Length of railway routes open for traffic, all gauges, as at 31 March. A double line counts once (route km, not track km).", "hi": "यातायात के लिए खुले रेल मार्गों की लंबाई, सभी गेज, 31 मार्च की स्थिति में। दोहरी लाइन एक ही बार गिनी जाती है (मार्ग किमी, ट्रैक किमी नहीं)।"}'::jsonb, 'km', 'multiple', true, null, 3, '[0, 75000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('rail_electrified_km', '{"en": "Electrified railway route length (route km)", "hi": "विद्युतीकृत रेल मार्ग की लंबाई (मार्ग किमी)"}'::jsonb, '{"en": "Electrified rail route", "hi": "विद्युतीकृत रेल मार्ग"}'::jsonb, '{"en": "Route km with overhead electric traction in operation. The state figures are broad gauge only (as on 31 Oct 2023).", "hi": "वे मार्ग किमी जिन पर बिजली से चलने वाली (ओवरहेड) व्यवस्था चालू है। राज्य आँकड़े केवल ब्रॉड गेज के हैं (31 अक्टूबर 2023 की स्थिति)।"}'::jsonb, 'km', 'multiple', true, null, 4, '[0, 75000]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('airports_operational', '{"en": "Number of operational airports (incl. heliports and water aerodromes)", "hi": "चालू हवाई अड्डों की संख्या (हेलीपोर्ट और जल हवाई अड्डे सहित)"}'::jsonb, '{"en": "Operational airports", "hi": "चालू हवाई अड्डे"}'::jsonb, '{"en": "Airports, heliports and water aerodromes with operations, as counted by the Ministry of Civil Aviation on the date of a reply in Parliament. Operational does not mean daily scheduled flights.", "hi": "संसद में उत्तर की तारीख पर नागर विमानन मंत्रालय द्वारा गिने गए चालू हवाई अड्डे, हेलीपोर्ट और जल हवाई अड्डे। चालू का मतलब रोज़ाना नियमित उड़ानें नहीं है।"}'::jsonb, 'airports', 'multiple', true, null, 5, '[0, 180]'::jsonb, 0, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('air_passengers_mn', '{"en": "Passengers handled at Indian airports (million, domestic + international)", "hi": "भारतीय हवाई अड्डों पर संभाले गए यात्री (मिलियन, घरेलू + अंतरराष्ट्रीय)"}'::jsonb, '{"en": "Air passengers", "hi": "हवाई यात्री"}'::jsonb, '{"en": "Passengers handled at all Indian airports in the financial year. Each trip is counted at both the departure and the arrival airport, so this is roughly twice the number of airline passengers carried.", "hi": "वित्त वर्ष में सभी भारतीय हवाई अड्डों पर संभाले गए यात्री। हर यात्रा प्रस्थान और आगमन दोनों हवाई अड्डों पर गिनी जाती है, इसलिए यह एयरलाइनों द्वारा ले जाए गए यात्रियों की संख्या का लगभग दोगुना है।"}'::jsonb, 'million', 'multiple', true, '"2020-21 and 2021-22 hit by COVID-19 travel restrictions."'::jsonb, 6, '[0, 450]'::jsonb, 2, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('metro_km', '{"en": "Operational metro rail length (km)", "hi": "चालू मेट्रो रेल लंबाई (किमी)"}'::jsonb, '{"en": "Metro network", "hi": "मेट्रो नेटवर्क"}'::jsonb, '{"en": "Length of metro rail lines in operation on the date of a Ministry of Housing and Urban Affairs reply in Parliament. From 2023 includes the operational part of the Delhi-Meerut RRTS (Namo Bharat). State values are given only where the state has one metro city or its cities are printed as one figure.", "hi": "संसद में आवास और शहरी कार्य मंत्रालय के उत्तर की तारीख पर चालू मेट्रो लाइनों की लंबाई। 2023 से दिल्ली-मेरठ RRTS (नमो भारत) का चालू भाग शामिल। राज्य आँकड़े केवल वहीं दिए गए हैं जहाँ राज्य में एक मेट्रो शहर है या उसके शहर एक ही आँकड़े में छपे हैं।"}'::jsonb, 'km', 'multiple', true, null, 7, '[0, 1200]'::jsonb, 1, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('port_cargo_mt', '{"en": "Cargo handled at Major Ports (million tonnes)", "hi": "प्रमुख पत्तनों पर संभाला गया कार्गो (मिलियन टन)"}'::jsonb, '{"en": "Major port cargo", "hi": "प्रमुख पत्तन कार्गो"}'::jsonb, '{"en": "Cargo loaded and unloaded at the 12 centrally owned Major Ports in the financial year (overseas + coastal). Excludes state-run and private non-major ports, which handle almost half of India''s cargo.", "hi": "वित्त वर्ष में केंद्र के 12 प्रमुख पत्तनों पर लादा और उतारा गया कार्गो (विदेशी + तटीय)। राज्य और निजी गैर-प्रमुख पत्तन शामिल नहीं, जो भारत का लगभग आधा कार्गो संभालते हैं।"}'::jsonb, 'million tonnes', 'multiple', true, null, 8, '[0, 1000]'::jsonb, 2, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('port_cargo_all_mt', '{"en": "Cargo handled at all Indian ports, major + non-major (million tonnes)", "hi": "सभी भारतीय पत्तनों पर संभाला गया कार्गो, प्रमुख + गैर-प्रमुख (मिलियन टन)"}'::jsonb, '{"en": "All-port cargo", "hi": "सभी पत्तनों का कार्गो"}'::jsonb, '{"en": "Total cargo handled at Major and non-major ports in the financial year, as stated in the ministry''s annual reports (approximate, revised in later editions).", "hi": "वित्त वर्ष में प्रमुख और गैर-प्रमुख पत्तनों पर संभाला गया कुल कार्गो, मंत्रालय की वार्षिक रिपोर्टों के अनुसार (अनुमानित, बाद के संस्करणों में संशोधित)।"}'::jsonb, 'million tonnes', 'multiple', true, null, 9, '[0, 1800]'::jsonb, 2, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.indicators (id, label, short_label, definition, unit, dataset, higher_is_better, break_note, sort, domain, decimals, map_domain) values ('port_cargo_nonmajor_mt', '{"en": "Cargo handled at non-major ports (million tonnes)", "hi": "गैर-प्रमुख पत्तनों पर संभाला गया कार्गो (मिलियन टन)"}'::jsonb, '{"en": "Non-major port cargo", "hi": "गैर-प्रमुख पत्तन कार्गो"}'::jsonb, '{"en": "Cargo at ports run by State Maritime Boards and private operators, by maritime state. Does not include the Major Port located in the same state.", "hi": "राज्य समुद्री बोर्डों और निजी संचालकों के पत्तनों पर कार्गो, समुद्री राज्यवार। उसी राज्य में स्थित प्रमुख पत्तन शामिल नहीं।"}'::jsonb, 'million tonnes', 'multiple', true, null, 10, '[0, 800]'::jsonb, 2, null) on conflict (id) do update set label = excluded.label, short_label = excluded.short_label, definition = excluded.definition, unit = excluded.unit, higher_is_better = excluded.higher_is_better, break_note = excluded.break_note, sort = excluded.sort, domain = excluded.domain, decimals = excluded.decimals, map_domain = excluded.map_domain;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('ls-2021-07-22-u504', 'Ministry of Jal Shakti, Department of Drinking Water and Sanitation (reply in Lok Sabha)', 'Lok Sabha Unstarred Question No. 504, answered 22.07.2021: Pure Drinking Water for All (Annex: State/ UT-wise status of tap water connections in rural households, as on 19.07.2021)', 'https://elibrary.sansad.in/handle/123456789/1436343', 'A', 'Government of India publication (Lok Sabha answer); reuse with attribution to the source', 'administrative data reported by states to the ministry; measures delivery, not use', 'States/UTs and All-India, rural households, JJM-IMIS', 'Share of rural households with a household tap connection as reported by States/UTs on JJM-IMIS; it counts connections provided, not whether water flows regularly or is safe (the Ministry''s own Functionality Assessment 2024 found 76% of tap connections functional). The denominator (total rural households) is revised by the States over time (e.g. Bihar 197.57 lakh in Feb 2021, 183.54 lakh in Jul 2021-Jul 2022, 166-168 lakh from 2023), so a state''s percentage can fall when its household count rises. Delhi and Chandigarh have no rural households in JJM and are not reported.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('ls-2021-02-11-s157', 'Ministry of Jal Shakti, Department of Drinking Water and Sanitation (reply in Lok Sabha)', 'Lok Sabha Starred Question No. 157, answered 11.02.2021: Piped Drinking Water Supply (Annex-I: Number of rural households having piped drinking water supply, as on 08.02.2021)', 'https://elibrary.sansad.in/handle/123456789/251924', 'A', 'Government of India publication (Lok Sabha answer); reuse with attribution to the source', 'administrative data reported by states to the ministry; measures delivery, not use', 'States/UTs and All-India, rural households, JJM-IMIS', 'Share of rural households with a household tap connection as reported by States/UTs on JJM-IMIS; it counts connections provided, not whether water flows regularly or is safe (the Ministry''s own Functionality Assessment 2024 found 76% of tap connections functional). The denominator (total rural households) is revised by the States over time (e.g. Bihar 197.57 lakh in Feb 2021, 183.54 lakh in Jul 2021-Jul 2022, 166-168 lakh from 2023), so a state''s percentage can fall when its household count rises. Delhi and Chandigarh have no rural households in JJM and are not reported.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
