insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('ls-2016-11-24-u1526', 'Ministry of Drinking Water and Sanitation (reply in Lok Sabha)', 'Lok Sabha Unstarred Question No. 1526, answered 24.11.2016: Review of SBM-G (Annexure-1: State/UT-wise Sanitation Coverage and ODF Villages)', 'https://sansad.in/getFile/loksabhaquestions/annex/10/AU1526.pdf?source=pqals', 'A', 'Government of India publication (Lok Sabha answer); reuse with attribution to the source', 'administrative data reported by states to the ministry; measures delivery, not use', 'States/UTs and All-India, rural households, SBM(G) MIS', 'Coverage of rural households with an individual household latrine as reported by States/UTs on the SBM(G) MIS against the SBM(G) baseline household list; it counts toilets built, not their use. The baseline was revised: answers in 2015-2016 give national coverage on 2.10.2014 as 42.01%, answers from July 2017 as 38.67-38.7%, so 2017 onwards is on a different denominator (break_before=1 on 2017-07-24). Some printed values exceed 100. Jammu & Kashmir includes Ladakh. Dadra & Nagar Haveli and Daman & Diu were separate UTs and are not combined here.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
