insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('srs-compendium-1971-2013-states', 'Office of the Registrar General & Census Commissioner, India', 'Compendium of India''s Fertility and Mortality Indicators 1971-2013 based on the Sample Registration System (SRS) - bigger States, Table 1', 'https://censusindia.gov.in/nada/index.php/catalog/33218/download/37035/SRS_COMP_INDIA_F_M_1971-2013.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'Infant mortality rate (Total column, col. 11) of each bigger State''s Table 1, transcribed for 1971-2003 from pdftotext -raw output of the compendium; source_page is the PDF page.', '19 bigger States/UT: AP, AS, BR, CT, DL, GJ, HR, JK, JH, KA, KL, MP, MH, OR, PB, RJ, TN, UP, WB; first printed IMR year varies (1971, 1972, 1981, 1990, 1999, 2000). All-India not repeated here (already in series_history.csv from the same compendium).', 'Sample-based estimates with sampling error, printed as whole numbers. Bihar, Madhya Pradesh and Uttar Pradesh rows from 1999 are starred as excluding Jharkhand, Chhattisgarh and Uttarakhand, so 1999 is a territorial break. Andhra Pradesh undivided throughout. J&K: no returns 1991-1997 and IMR printed only from 2000; Delhi IMR printed only from 1990. Smaller States/UTs have no IMR in their Table 1 and are not included.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('census2001-hhaa-keyresults-jammu-and-kashmir', 'Office of the Registrar General & Census Commissioner, India', 'Census of India 2001 - Where and How People Live? Data on Housing Stock, Household Amenities and Assets - Jammu and Kashmir Key Results (presentation PDF)', 'https://censusindia.gov.in/nada/index.php/catalog/27646/download/30794/Data%20on%20Housing%20StockHousehold%20Amenities%20and%20Assets%20Presentation%20Jammu%20and%20Kashmir.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'State key-results slides from the 2001 Houselisting and Housing Census; State column read from pdftotext -raw text. Every recorded value was cross-checked against State-level counts in Census 2001 tables H-08, H-09, H-11 and H-13 (within 0.05 points after rounding); values that failed were left out.', 'Jammu and Kashmir (and India column), Census 2001, total (rural+urban) households.', 'Slides print one decimal. Latrine is printed only as ''No latrine'' within the house, so latrine-within-premises is not recorded from this deck. The India ''Kerosene'' column on the cooking-fuel slide differs between decks (6.5 or 9.8); LPG values used here were each checked against the H-11 table.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
