insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('pib-2273854', 'Press Information Bureau, Ministry of Defence', 'The Defence Decade (17 Jun 2026)', 'https://www.pib.gov.in/PressReleasePage.aspx?PRID=2273854', 'A', 'Government of India press release; public record, cited with attribution.', 'Government press backgrounder quoting DDP figures.', 'Defence production 2014-15 (Rs 46,429 crore); defence exports 2013-14 (Rs 686 crore)', 'A press statement, not a statistical table; no definition or revision history is given.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
