insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('sipri-milex-const-usd', 'Stockholm International Peace Research Institute (SIPRI)', 'SIPRI Military Expenditure Database, India: Constant (2024) US$', 'https://www.sipri.org/databases/milex', 'B', 'SIPRI terms and conditions (https://www.sipri.org/about/terms-and-conditions): free for non-commercial use under SIPRI''s fair-use policy, which allows reproducing less than 10 per cent of a published data set, with a clear reference to SIPRI. Credit line: ''Information from the Stockholm International Peace Research Institute (SIPRI) Military Expenditure Database, https://doi.org/10.55163/CQGC9685''. Commercial use or reproducing more than 10 per cent needs SIPRI''s written permission. This site reproduces only India''s rows.', 'SIPRI compiles military spending from official budgets and other sources using its own definition (armed forces, defence ministries, paramilitary forces judged trained and equipped for military operations, military space; personnel including pensions, operations, procurement, R&D, construction, military aid). SIPRI footnote for India: India: The figures for India include expenditure on the paramilitary forces of the Border Security Force, the Central Reserve Police Force, the Assam Rifles, the Indo-Tibetan Border Police and, from 2007, the Sashastra Seema Bal but do not include spending on military nuclear activities.', 'India, 70 annual values (US$ m at constant 2024 prices and exchange rates, divided by 1000 to give US$ bn)', 'Military expenditure is an input measure; SIPRI says it is not directly related to military capability or security. SIPRI revises the whole series with each edition and the constant-dollar base year changes. Pre-1988 Indian figures are SIPRI estimates.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('sipri-milex-inr-fy', 'Stockholm International Peace Research Institute (SIPRI)', 'SIPRI Military Expenditure Database, India: Local currency financial years', 'https://www.sipri.org/databases/milex', 'B', 'SIPRI terms and conditions (https://www.sipri.org/about/terms-and-conditions): free for non-commercial use under SIPRI''s fair-use policy, which allows reproducing less than 10 per cent of a published data set, with a clear reference to SIPRI. Credit line: ''Information from the Stockholm International Peace Research Institute (SIPRI) Military Expenditure Database, https://doi.org/10.55163/CQGC9685''. Commercial use or reproducing more than 10 per cent needs SIPRI''s written permission. This site reproduces only India''s rows.', 'SIPRI compiles military spending from official budgets and other sources using its own definition (armed forces, defence ministries, paramilitary forces judged trained and equipped for military operations, military space; personnel including pensions, operations, procurement, R&D, construction, military aid). SIPRI footnote for India: India: The figures for India include expenditure on the paramilitary forces of the Border Security Force, the Central Reserve Police Force, the Assam Rifles, the Indo-Tibetan Border Police and, from 2007, the Sashastra Seema Bal but do not include spending on military nuclear activities.', 'India, 71 annual values (rupees at current prices, financial year April-March (SIPRI FY y = April y to March y+1), divided by 1e7 to give Rs crore)', 'Military expenditure is an input measure; SIPRI says it is not directly related to military capability or security. SIPRI revises the whole series with each edition and the constant-dollar base year changes. Pre-1988 Indian figures are SIPRI estimates.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('sipri-milex-pct-gdp', 'Stockholm International Peace Research Institute (SIPRI)', 'SIPRI Military Expenditure Database, India: Share of GDP', 'https://www.sipri.org/databases/milex', 'B', 'SIPRI terms and conditions (https://www.sipri.org/about/terms-and-conditions): free for non-commercial use under SIPRI''s fair-use policy, which allows reproducing less than 10 per cent of a published data set, with a clear reference to SIPRI. Credit line: ''Information from the Stockholm International Peace Research Institute (SIPRI) Military Expenditure Database, https://doi.org/10.55163/CQGC9685''. Commercial use or reproducing more than 10 per cent needs SIPRI''s written permission. This site reproduces only India''s rows.', 'SIPRI compiles military spending from official budgets and other sources using its own definition (armed forces, defence ministries, paramilitary forces judged trained and equipped for military operations, military space; personnel including pensions, operations, procurement, R&D, construction, military aid). SIPRI footnote for India: India: The figures for India include expenditure on the paramilitary forces of the Border Security Force, the Central Reserve Police Force, the Assam Rifles, the Indo-Tibetan Border Police and, from 2007, the Sashastra Seema Bal but do not include spending on military nuclear activities.', 'India, 70 annual values (share of GDP, calendar year, multiplied by 100 to give per cent)', 'Military expenditure is an input measure; SIPRI says it is not directly related to military capability or security. SIPRI revises the whole series with each edition and the constant-dollar base year changes. Pre-1988 Indian figures are SIPRI estimates.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, 