insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('sipri-atd-imports', 'Stockholm International Peace Research Institute (SIPRI)', 'SIPRI Arms Transfers Database: volume of transfers of major arms, India as recipient (TIV)', 'https://armstransfers.sipri.org/ArmsTransfer/ImportExport', 'B', 'SIPRI terms and conditions (https://www.sipri.org/about/terms-and-conditions): free for non-commercial use under SIPRI''s fair-use policy, which allows reproducing less than 10 per cent of a published data set, with a clear reference to SIPRI. Credit line: ''Information from the Stockholm International Peace Research Institute (SIPRI) Arms Transfers Database, https://www.sipri.org/databases/armstransfers''. Commercial use or reproducing more than 10 per cent needs SIPRI''s written permission. This site reproduces only India''s rows.', 'Deliveries of major conventional weapons, valued in SIPRI trend-indicator values (TIV). The TIV is based on known unit production costs of a core set of weapons and represents the transfer of military resources, not the financial value of the transfer.', 'India, 76 annual values, 1950-2025', 'TIV is not money: SIPRI says TIV figures do not represent sales prices and should not be compared with GDP, military expenditure, sales values or export-licence values. Major arms only (no small arms or most ammunition). Years with no identified deliveries are blank in SIPRI and are left out here. SIPRI revises past years as new deliveries are identified.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('sipri-atd-exports', 'Stockholm International Peace Research Institute (SIPRI)', 'SIPRI Arms Transfers Database: volume of transfers of major arms, India as supplier (TIV)', 'https://armstransfers.sipri.org/ArmsTransfer/ImportExport', 'B', 'SIPRI terms and conditions (https://www.sipri.org/about/terms-and-conditions): free for non-commercial use under SIPRI''s fair-use policy, which allows reproducing less than 10 per cent of a published data set, with a clear reference to SIPRI. Credit line: ''Information from the Stockholm International Peace Research Institute (SIPRI) Arms Transfers Database, https://www.sipri.org/databases/armstransfers''. Commercial use or reproducing more than 10 per cent needs SIPRI''s written permission. This site reproduces only India''s rows.', 'Deliveries of major conventional weapons, valued in SIPRI trend-indicator values (TIV). The TIV is based on known unit production costs of a core set of weapons and represents the transfer of military resources, not the financial value of the transfer.', 'India, 41 annual values, 1950-2025', 'TIV is not money: SIPRI says TIV figures do not represent sales prices and should not be compared with GDP, military expenditure, sales values or export-licence values. Major arms only (no small arms or most ammunition). Years with no identified deliveries are blank in SIPRI and are left out here. SIPRI revises past years as new deliveries are identified.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('wb-ms-mil-xpnd-gd-zs', 'World Bank WDI, original provider: SIPRI Military Expenditure Database', 'Military expenditure (% of GDP)', 'https://data.worldbank.org/indicator/MS.MIL.XPND.GD.ZS?locations=IN', 'B', 'SIPRI terms and conditions, as stated in the World Bank metadata (License_Type: ''SIPRI terms and conditions''); not CC BY. Non-commercial use only; more than 10% of a SIPRI data set needs SIPRI''s permission.', 'SIPRI''s military expenditure as % of GDP, republished by the World Bank. Same figures as SIPRI''s own file; kept as a separate line because the World Bank may lag or round differently.', 'India, 66 annual values', 'Republished; check the original provider before using a single value in a claim.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('wb-ms-mil-totl-p1', 'World Bank WDI, original provider: International Institute for Strategic Studies (IISS), The Military Balance', 'Armed forces personnel, total', 'https://data.worldbank.org/indicator/MS.MIL.TOTL.P1?locations=IN', 'B', 'CC BY 4.0 (World Bank metadata License_Type ''CC BY-4.0''); original data from IISS The Military Balance.', 'Active-duty military personnel, including paramilitary forces judged able to support or replace regular forces. Excludes reservists. Some Military Balance figures are IISS estimates.', 'India, 33 annual values', 'Republished; check the original provider before using a single value in a claim.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('ddp-dashboard-production', 'Department of Defence Production, Ministry of Defence', 'DDP dashboard: value of defence production (Rs crore), by financial year', 'https://ddpdashboard.gov.in/', 'A', 'Government of India (Department of Defence Production) public dashboard. No licence statement was found on the dashboard; figures are cited with attribution to DDP, Ministry of Defence.', 'Value of production reported to DDP by Defence PSUs, the new DPSUs formed from the Ordnance Factory Board, other PSUs making defence items, and private companies.', 'India, 10 financial years', 'Self-reported by producers; the latest year may be provisional and is revised. Earlier PIB releases quote other vintages (e.g. Rs 1,26,887 crore for 2023-24 in July 2024, now Rs 1,27,434.48 crore).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('ddp-dashboard-exports', 'Department of Defence Production, Ministry of Defence', 'DDP dashboard: defence exports (Rs crore), by financial year', 'https://ddpdashboard.gov.in/', 'A', 'Government of India (Department of Defence Production) public dashboard. No licence statement was found on the dashboard; figures are cited with attribution to DDP, Ministry of Defence.', 'Exports by private companies (against DDP export authorisations), SCOMET items, and DPSU exports, as compiled by DDP.', 'India, 10 completed financial years (the current year''s running total is left out)', 'A money value in current rupees, unlike SIPRI TIV. Includes parts, components and services, not only major weapons. The private-sector figure comes from the export-authorisation system.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('econ-rbi-hbs-2017-18-t1', 'Reserve Bank of India (Handbook of Statistics on the Indian Economy); original source: National Statistics Office (NSO/CSO), MoSPI', 'Table 1: Macro-Economic Aggregates (At Current Prices), Handbook of Statistics on the Indian Economy 2017-18', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/TABLE103EBE23AD5EE4D6A9A62A9D939677B34.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Per capita GDP (and, from Table 1, consumption of fixed capital, GDP and primary income receivable from ROW (net) = net factor income from abroad) copied from the item rows of the Excel table. For each base year, every fiscal year is taken from the latest HBS edition that still prints that year at that base (later editions revise earlier years and drop the oldest). cfc_share_gdp is CALCULATED here as CFC / GDP x 100 from two cells of the same table and edition. Values in Rs billion editions (2017-18) converted to Rs crore x 100.', 'All India; 2011-12 to 2011-12 (1 periods); indicators: cfc_current_inr_crore, cfc_share_gdp, gdp_per_capita_current, nfia_current_inr_crore; 4 values', 'Edition-to-edition revisions mean adjacent years can come from different vintages of the same base series (edition named in each row note). Latest years are provisional/revised estimates as flagged in the table notes. 2025-26 edition prints base 2011-12 only to 2022-23 and base 2022-23 from 2022-23.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('econ-rbi-hbs-2017-18-t2', 'Reserve Bank of India (Handbook of Statistics on the Indian Economy); original source: National Statistics Office (NSO/CSO), MoSPI', 'Table 2: Macro-Economic Aggregates (At Constant Prices), Handbook of Statistics on the Indian Economy 2017-18', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/TABLE230A9E0241AF44712888C63BFBA1B2677.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Per capita GDP (and, from Table 1, consumption of fixed capital, GDP and primary income receivable from ROW (net) = net factor income from abroad) copied from the item rows of the Excel table. For each base year, every fiscal year is taken from the latest HBS edition that still prints that year at that base (later editions revise earlier years and drop the oldest). cfc_share_gdp is CALCULATED here as CFC / GDP x 100 from two cells of the same table and edition. Values in Rs billion editions (2017-18) converted to Rs crore x 100.', 'All India; 2011-12 to 2011-12 (1 periods); indicators: gdp_per_capita_constant; 1 values', 'Edition-to-edition revisions mean adjacent years can come from different vintages of the same base series (edition named in each row note). Latest years are provisional/revised estimates as flagged in the table notes. 2025-26 edition prints base 2011-12 only to 2022-23 and base 2022-23 from 2022-23.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
