insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('econ-rbi-hbs-2025-26-trade', 'Reserve Bank of India (Handbook of Statistics on the Indian Economy); original source: Directorate General of Commercial Intelligence and Statistics (DGCI&S), Ministry of Commerce and Industry', 'Table 111: India''s Foreign Trade - US Dollar, HBS 2025-26 (table covers 1987-88 to 2025-26)', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/111T_HBIE310720263F56EBA18003472381EA6E8BC8EA42F0.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Total exports and total imports columns (oil + non-oil), US$ million, divided by 1000 to give US$ billion. Each fiscal year is taken from the latest downloaded HBS edition that prints it; years used from this edition: 1987-88, 1988-89, 1989-90, 1990-91, 1991-92, 1992-93, 1993-94, 1994-95, 1995-96, 1996-97, 1997-98, 1998-99, 1999-00, 2000-01, 2001-02, 2002-03, 2003-04, 2004-05, 2005-06, 2006-07, 2007-08, 2008-09, 2009-10, 2010-11, 2011-12, 2012-13, 2013-14, 2014-15, 2015-16, 2016-17, 2017-18, 2018-19, 2019-20, 2020-21, 2021-22, 2022-23, 2023-24, 2024-25, 2025-26', 'All India; 1987-88 to 2025-26 (39 periods); indicators: trade_exports_usd_bn, trade_imports_usd_bn; 78 values', 'Fiscal years (April-March). DGCI&S customs-basis merchandise trade, not balance-of-payments basis. No HBS edition checked prints US$ trade before 1970-71, so 1950-51 to 1969-70 is a gap.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('econ-comtrade-india-hs2', 'United Nations Statistics Division, UN Comtrade Database (data as reported by India / DGCI&S)', 'UN Comtrade public preview API: India (reporter 699), partner World (0), annual, HS chapters (AG2) and TOTAL, exports and imports', 'https://comtradeapi.un.org/public/v1/preview/C/A/HS?reporterCode=699&period=2023&partnerCode=0&flowCode=X,M&cmdCode=AG2&includeDesc=true', 'B', 'UN Comtrade terms of use (https://comtradeplus.un.org/); free public preview API, cite as ''United Nations Comtrade Database''.', 'One call per calendar year 2005-2025 for cmdCode=AG2 (all 97 HS chapters) and one for TOTAL, flows X and M. Kept records with partnerCode 0, partner2Code 0, customsCode C00, motCode 0. value_usd = primaryValue as returned. For every year and flow the 97 chapters sum to TOTAL (difference under US$10). HS vintage per year: H2 2005-08, H3 2009-12, H4 2013-16, H5 2017-21, H6 2022-25.', 'India, world; calendar years 2005-2025; 4116 rows (97 HS chapters + TOTAL x 2 flows x 21 years)', 'Calendar years, so totals differ from the April-March DGCI&S figures in series_econ.csv. Chapter-level (HS 2-digit) only; grouping into HS sections is left to the site. 2025 data as available on 2026-10-16 and may be revised.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('econ-rbi-hsis-2024-25-t116', 'Reserve Bank of India (Handbook of Statistics on Indian States 2024-25); original source: Annual Survey of Industries (ASI), MoSPI', 'Table 116: State-Wise Number Of Factories (ASI), HSIS 2024-25', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/116T_11122025F5E48BEEC5354EC7ABF7A9B4127694AE.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'State columns x year rows read from the Excel table; cells printed as . (not applicable) or - (not available) skipped.', '37 regions incl. All India; 2004-05 to 2023-24 (20 periods); indicators: factories; 652 values', 'Andhra Pradesh undivided to 2011-12, Telangana separate from 2012-13 (break flagged). Jammu & Kashmir includes Ladakh to 2018-19 (break at 2019-20). Separate Dadra & Nagar Haveli and Daman & Diu figures before 2020-21 not used (no matching region code); merged UT from 2020-21. Arunachal from 2014-15, Mizoram from 2019-20, Lakshadweep from 2023-24. The All-India number of factories jumps from 158,877 (2009-10) to 211,660 (2010-11); the table gives no explanation. ASI covers registered factories only. GVA is at current prices.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('econ-rbi-hsis-2024-25-t122', 'Reserve Bank of India (Handbook of Statistics on Indian States 2024-25); original source: Annual Survey of Industries (ASI), MoSPI', 'Table 122: State-Wise Number Of Workers (ASI), HSIS 2024-25', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/122T_11122025E8D00E32A3384D3CAEA44E12BC9D418A.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'State columns x year rows read from the Excel table; cells printed as . (not applicable) or - (not available) skipped.', '37 regions incl. All India; 2004-05 to 2023-24 (20 periods); indicators: factory_workers; 652 values', 'Andhra Pradesh undivided to 2011-12, Telangana separate from 2012-13 (break flagged). Jammu & Kashmir includes Ladakh to 2018-19 (break at 2019-20). Separate Dadra & Nagar Haveli and Daman & Diu figures before 2020-21 not used (no matching region code); merged UT from 2020-21. Arunachal from 2014-15, Mizoram from 2019-20, Lakshadweep from 2023-24. The All-India number of factories jumps from 158,877 (2009-10) to 211,660 (2010-11); the table gives no explanation. ASI covers registered factories only. GVA is at current prices.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('econ-rbi-hsis-2024-25-t128', 'Reserve Bank of India (Handbook of Statistics on Indian States 2024-25); original source: Annual Survey of Industries (ASI), MoSPI', 'Table 128: State-Wise Gross Value Added (ASI), HSIS 2024-25', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/128T_11122025BC6190C6B6B14014896D4E11A42A8E44.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'State columns x year rows read from the Excel table; cells printed as . (not applicable) or - (not available) skipped. GVA printed in Rs lakh, divided by 100 to Rs crore.', '37 regions incl. All India; 2004-05 to 2023-24 (20 periods); indicators: factory_gva_inr_crore; 652 values', 'Andhra Pradesh undivided to 2011-12, Telangana separate from 2012-13 (break flagged). Jammu & Kashmir includes Ladakh to 2018-19 (break at 2019-20). Separate Dadra & Nagar Haveli and Daman & Diu figures before 2020-21 not used (no matching region code); merged UT from 2020-21. Arunachal from 2014-15, Mizoram from 2019-20, Lakshadweep from 2023-24. The All-India number of factories jumps from 158,877 (2009-10) to 211,660 (2010-11); the table gives no explanation. ASI covers registered factories only. GVA is at current prices.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('econ-rbi-hbs-2012-13-t33', 'Reserve Bank of India (Handbook of Statistics on the Indian Economy 2012-13); original source: Annual Survey of Industries, MoSPI', 'Table 33: Annual Survey of Industries - Principal Characteristics, HBS 2012-13 (1990-91 to 2010-11)', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/033T_BST130913.xls', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'All-India number of factories (column L) and number of workers (column AD) for 1990-91 to 2003-04; later years taken from HSIS 2024-25 instead (dataset asi_rbi_hsis).', 'All India; 1990-91 to 2003-04 (14 periods); indicators: factories, factory_workers; 28 values', 'All-India only. Earlier ASI years (before 1990-91) were not found in any downloaded RBI table; MoSPI ASI time series could not be reached. 1998-99 persons-engaged cell is blank in the source (not used).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('econ-mospi-plfs-ar-2017-18', 'National Statistical Office (NSO), Ministry of Statistics and Programme Implementation (MoSPI)', 'Annual Report, Periodic Labour Force Survey (PLFS) 2017-18 (July-June)', 'https://mospi.gov.in/sites/default/files/publication_reports/Annual%20Report%2C%20PLFS%202017-18_31052019.pdf', 'A', 'Government of India publication; reuse with attribution under the Government Open Data Use Licence - India / National Data Sharing and Accessibility Policy (licence not restated inside the file)', 'PDF converted to text with xpdf pdftotext -table. Industry: Table (27) rural+urban persons panel, NIC-2008 sections; agriculture = section A, manufacturing = C, construction = F (as printed); industry share = B+C+D+E+F and services share = G..U are CALCULATED here as sums of printed sections (dataset plfs_ar_calc). Each row accepted only if its sections sum to 100 within 0.6. WPR and UR: tables for each State/UT, panel ''age group: 15 years and above'', column (10) rural+urban persons; every row checked that the rural+urban value lies between the rural and urban values.', '35 regions incl. All India; 2017-18 to 2017-18 (1 periods); indicators: jobs_agri_share, jobs_construction_share, jobs_industry_share, jobs_manufacturing_share, jobs_services_share, unemployment_rate, wpr; 245 values', 'Survey estimates with sampling error (RSE tables in the report). Agricultural year July-June. Separate Dadra & Nagar Haveli and Daman & Diu rows (pre-merger) not used. Jammu & Kashmir includes Ladakh in 2017-18 and 2018-19. 2020-21 and 2023-24 annual reports could not be located (URL guesses returned 404; MoSPI publication listing API returns 403).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
