insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('econ-mospi-plfs-ar-2021-22', 'National Statistical Office (NSO), Ministry of Statistics and Programme Implementation (MoSPI)', 'Annual Report, Periodic Labour Force Survey (PLFS) 2021-22 (July-June)', 'https://mospi.gov.in/sites/default/files/publication_reports/AnnualReportPLFS2021-22F1.pdf', 'A', 'Government of India publication; reuse with attribution under the Government Open Data Use Licence - India / National Data Sharing and Accessibility Policy (licence not restated inside the file)', 'PDF converted to text with xpdf pdftotext -table. Industry: Table (27) rural+urban persons panel, NIC-2008 sections; agriculture = section A, manufacturing = C, construction = F (as printed); industry share = B+C+D+E+F and services share = G..U are CALCULATED here as sums of printed sections (dataset plfs_ar_calc). Each row accepted only if its sections sum to 100 within 0.6. WPR and UR: tables for each State/UT, panel ''age group: 15 years and above'', column (10) rural+urban persons; every row checked that the rural+urban value lies between the rural and urban values.', '37 regions incl. All India; 2021-22 to 2021-22 (1 periods); indicators: jobs_agri_share, jobs_construction_share, jobs_industry_share, jobs_manufacturing_share, jobs_services_share, unemployment_rate, wpr; 259 values', 'Survey estimates with sampling error (RSE tables in the report). Agricultural year July-June. Separate Dadra & Nagar Haveli and Daman & Diu rows (pre-merger) not used. Jammu & Kashmir includes Ladakh in 2017-18 and 2018-19. 2020-21 and 2023-24 annual reports could not be located (URL guesses returned 404; MoSPI publication listing API returns 403).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('econ-mospi-plfs-ar-2022-23', 'National Statistical Office (NSO), Ministry of Statistics and Programme Implementation (MoSPI)', 'Annual Report, Periodic Labour Force Survey (PLFS) 2022-23 (July-June)', 'https://mospi.gov.in/sites/default/files/publication_reports/AR_PLFS_2022_23N.pdf', 'A', 'Government of India publication; reuse with attribution under the Government Open Data Use Licence - India / National Data Sharing and Accessibility Policy (licence not restated inside the file)', 'PDF converted to text with xpdf pdftotext -table. Industry: Table (16) rural+urban persons panel, NIC-2008 sections; agriculture = section A, manufacturing = C, construction = F (as printed); industry share = B+C+D+E+F and services share = G..U are CALCULATED here as sums of printed sections (dataset plfs_ar_calc). Each row accepted only if its sections sum to 100 within 0.6. WPR and UR: tables for each State/UT, panel ''age group: 15 years and above'', column (10) rural+urban persons; every row checked that the rural+urban value lies between the rural and urban values.', '37 regions incl. All India; 2022-23 to 2022-23 (1 periods); indicators: jobs_agri_share, jobs_construction_share, jobs_industry_share, jobs_manufacturing_share, jobs_services_share, unemployment_rate, wpr; 259 values', 'Survey estimates with sampling error (RSE tables in the report). Agricultural year July-June. Separate Dadra & Nagar Haveli and Daman & Diu rows (pre-merger) not used. Jammu & Kashmir includes Ladakh in 2017-18 and 2018-19. 2020-21 and 2023-24 annual reports could not be located (URL guesses returned 404; MoSPI publication listing API returns 403).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('econ-mospi-esankhyiki-plfs-api', 'National Statistical Office (NSO), MoSPI - eSankhyiki API', 'PLFS API getData (indicator 2 WPR, indicator 3 UR), annual, calendar years', 'https://api.mospi.gov.in/api/plfs/getData?indicator_code=3&frequency_code=1&gender_code=3&sector_code=3&Format=JSON', 'A', 'Government of India publication; reuse with attribution under the Government Open Data Use Licence - India / National Data Sharing and Accessibility Policy (licence not restated inside the file)', 'All pages fetched with curl (no key needed). Kept records with weekly_status PS+SS, AgeGroup 15 years and above, religion/socialGroup/General_Education all, gender person, sector rural + urban, frequency Annually; year_type is Calendar Year for all.', '37 regions incl. All India; 2022 (Jan-Dec) to 2025 (Jan-Dec) (4 periods); indicators: unemployment_rate, wpr; 296 values', 'Calendar years (January-December), so not directly comparable with the July-June annual-report series (separate dataset). The API holds broad-industry distribution only for CWS, so no ps+ss sector shares were taken from it.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('wb-sh-med-beds-zs', 'World Bank (World Development Indicators); source organisation: WHO data, supplemented by country data', 'Hospital beds (per 1,000 people), SH.MED.BEDS.ZS, India', 'https://api.worldbank.org/v2/country/IND/indicator/SH.MED.BEDS.ZS?format=json&per_page=100', 'A', 'CC BY 4.0 (World Bank open data terms)', 'All non-null annual values for India copied from the World Bank API (dataset last updated 2026-10-08). Values with floating-point noise (1960-1991) rounded to 4 decimals; 2000-2021 values are printed to 2 decimals and copied as is.', 'All-India only; 1960, 1970, 1975, 1980, 1981, 1985, 1987, 1991, 2000-2021; 30 values', 'Covers public and private inpatient beds (World Bank definition). The 2000-2021 values fall smoothly every year (2.13 to 1.59), which suggests modelled or interpolated figures rather than yearly counts; the source does not say. Large unexplained jump between 1991 (0.787) and 2000 (2.13): flagged as a break. No state-level data. No WHO norm for hospital beds is recorded because no official WHO document stating one was found.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('who-gho-hwf-0001', 'World Health Organization, Global Health Observatory (National Health Workforce Accounts data portal, December 2025 update)', 'Medical doctors (per 10,000), HWF_0001, India', 'https://ghoapi.azureedge.net/api/HWF_0001?$filter=SpatialDim%20eq%20''IND''', 'A', 'WHO GHO data; reuse with attribution to WHO under WHO terms of use (no licence stated in the API response)', 'All annual values for India copied exactly from the WHO GHO OData API (''Value'' field). WHO''s matching count series HWF_0002 gives 1,349,679 doctors for 2023, the same figure as the National Medical Commission count of MBBS doctors registered up to 31.12.2022 printed in National Health Profile 2023 Table 5.1, so the series is based on cumulative registrations.', 'All-India only; 1991, 1995-2024; 31 values', 'Based on registered doctors (cumulative registrations with state medical councils/NMC), which include doctors who have died, retired, emigrated or are registered in more than one state; not a count of active doctors. Allopathic (modern medicine) only; AYUSH practitioners excluded. 1991 value (12.31) is far above 1995 (4.79) with no explanation from WHO: break flagged at 1995. 2011 (7.31) is out of line with 2010 and 2012.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('who-gho-hwf-0006', 'World Health Organization, Global Health Observatory (National Health Workforce Accounts data portal, December 2025 update)', 'Nursing and midwifery personnel (per 10,000), HWF_0006, India', 'https://ghoapi.azureedge.net/api/HWF_0006?$filter=SpatialDim%20eq%20''IND''', 'A', 'WHO GHO data; reuse with attribution to WHO under WHO terms of use (no licence stated in the API response)', 'All annual values for India copied exactly from the WHO GHO OData API (''Value'' field).', 'All-India only; 2005-2012, 2014-2018, 2020-2024; 18 values', 'Based on registration data (nursing and midwifery councils), not on active workforce. 2018 (17.0) is well below 2017 (21.82) and 2020 (23.27) and is likely a reporting change; WHO gives no note. No values for 2013 and 2019.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('who-gho-hwf-0001-0006', 'World Health Organization, Global Health Observatory; sum calculated by Tathya', 'Medical doctors (HWF_0001) plus nursing and midwifery personnel (HWF_0006), per 10,000, India', 'https://ghoapi.azureedge.net/api/HWF_0001?$filter=SpatialDim%20eq%20''IND''', 'A', 'WHO GHO data; reuse with attribution to WHO under WHO terms of use (no licence stated in the API response)', 'For each year in which WHO publishes both series, Tathya adds the published doctors density (HWF_0001) and nursing and midwifery density (HWF_0006). Both use the same WHO population denominator. The two inputs are written in each row''s note. Second input URL: https://ghoapi.azureedge.net/api/HWF_0006?$filter=SpatialDim%20eq%20''IND''', 'All-India only; 2005-2012, 2014-2018, 2020-2024; 18 values', 'Sum of rounded published values (may differ from an exact calculation by 0.01). Inherits the registration basis of both series and the 2018 nursing outlier. This is the aggregate that WHO''s 44.5 per 10,000 SDG index threshold refers to (physicians, nurses and midwives).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('who-gshrh-2016', 'World Health Organization', 'Global strategy on human resources for health: Workforce 2030 (2016), Annex 1', 'https://iris.who.int/server/api/core/bitstreams/3ef6ee65-42fa-4d2b-9c75-d55b2df17f9a/content', 'A', '© World Health Organization 2016', 'Benchmark only, no data rows. Annex 1 (PDF page 42) states that ''an indicative threshold of an aggregate density of 4.45 physicians, nurses and midwives per 1000 population was identified'' (= 44.5 per 10,000), the median of SDG tracer indicator attainment.', 'Benchmark value used in the indicator definitions of doctors_per_10000 and health_workers_per_10000', 'WHO calls it an indicative threshold used for needs-based workforce estimates, not a mandatory norm. It covers doctors, nurses and midwives together, not doctors alone.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('lok-sabha-2024-11-29-sq80', 'Lok Sabha Secretariat (sansad.in); answer by Ministry of Health and Family Welfare', 'Lok Sabha Starred Question No. 80, ''MBBS Doctor-Population Ratio'', answered 29.11.2024', 'https://sansad.in/getFile/lsapps/loksabhaquestions/annex/183/AS80_qA0tQu.pdf?source=lsapps', 'A', 'Parliament of India proceedings; public record, reuse with attribution', 'Ratio ''around 1:811'' copied from the Statement; 13,86,145 registered allopathic doctors as on November 2024. One value per calendar year (latest answer in the year); earlier 2024 answers (02.08.2024, USQ 1887 and 2067) printed 1:836.', 'All-India, one value', 'Government estimate, not a measured ratio: counts all registered allopathic doctors and registered AYUSH practitioners and assumes 80% are available; registrations are cumulative. The ''WHO standard of 1:1000'' that answers cite was not found in any WHO document we opened; WHO''s 2016 workforce strategy uses 44.5 doctors, nurses and midwives per 10,000 instead. All-India only; answers decline to give state-wise ratios.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('lok-sabha-2025-08-01-uq2256', 'Lok Sabha Secretariat (sansad.in); answer by Ministry of Health and Family Welfare', 'Lok Sabha Unstarred Question No. 2256, ''Doctor-population Ratio'', answered 01.08.2025', 'https://sansad.in/getFile/lsapps/loksabhaquestions/annex/185/AU2256_qD4i4E.pdf?source=lsapps', 'A', 'Parliament of India proceedings; public record, reuse with attribution', 'Ratio 1:811 copied from the answer; 13,86,157 registered allopathic doctors, 7,51,768 AYUSH practitioners. One value per calendar year (latest answer in the year); earlier 2024 answers (02.08.2024, USQ 1887 and 2067) printed 1:836.', 'All-India, one value', 'Government estimate, not a measured ratio: counts all registered allopathic doctors and registered AYUSH practitioners and assumes 80% are available; registrations are cumulative. The ''WHO standard of 1:1000'' that answers cite was not found in any WHO document we opened; WHO''s 2016 workforce strategy uses 44.5 doctors, nurses and midwives per 10,000 instead. All-India only; answers decline to give state-wise ratios.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('lok-sabha-2026-07-31-uq2141', 'Lok Sabha Secretariat (sansad.in); answer by Ministry of Health and Family Welfare', 'Lok Sabha Unstarred Question No. 2141, ''Shortage of Doctors'', answered 31.07.2026', 'https://sansad.in/getFile/lsapps/loksabhaquestions/annex/188/AU2141_H2lWeF.pdf?source=lsapps', 'A', 'Parliament of India proceedings; public record, reuse with attribution', 'Ratio 1:778 copied from the answer; 15,35,155 registered allopathic doctors (IMR), 7,51,768 AYUSH practitioners. One value per calendar year (latest answer in the year); earlier 2024 answers (02.08.2024, USQ 1887 and 2067) printed 1:836.', 'All-India, one value', 'Government estimate, not a measured ratio: counts all registered allopathic doctors and registered AYUSH practitioners and assumes 80% are available; registrations are cumulative. The ''WHO standard of 1:1000'' that answers cite was not found in any WHO document we opened; WHO''s 2016 workforce strategy uses 44.5 doctors, nurses and midwives per 10,000 instead. All-India only; answers decline to give state-wise ratios.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('cbhi-nhp-2020-t6111', 'Central Bureau of Health Intelligence (DGHS, MoHFW); original source: NMC/MCI website state-wise list of medical colleges', 'National Health Profile 2020, Table 6.1.1.1: State-wise details of Medical Colleges and MBBS seats 2019-20', 'https://cbhidghs.mohfw.gov.in/sites/default/files/NHP/National_Health_Profile_2020.pdf', 'A', 'Government of India publication (CBHI, DGHS, MoHFW); reuse with attribution', 'Govt / Pvt / Total colleges and Govt / Pvt / Total MBBS seats copied from the printed state-wise table (page 385). Printed India total row used for IN.', '33 states/UTs + India; 2019-20', 'Dadra & Nagar Haveli and Daman & Diu printed as separate rows, so left out (DNH: 1 Govt college, 150 seats); rows for Imphal and Nepal (all zero) ignored. J&K includes Ladakh. "Pvt." is not further split into trust/society/deemed. The NHP 2021 edition reprints this table with Assam as 6 colleges (NHP 2020 prints 7); the original NHP 2020 edition was used because its columns add up to the printed totals.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('cbhi-nhp-2022-t6111', 'Central Bureau of Health Intelligence (DGHS, MoHFW); original source: NMC website state-wise list of medical colleges', 'National Health Profile 2022, Table 6.1.1.1: State-wise details of Medical Colleges and MBBS seats as on September, 2022', 'https://cbhidghs.mohfw.gov.in/sites/default/files/2024-09/national-health-profile-2022.pdf', 'A', 'Government of India publication (CBHI, DGHS, MoHFW); reuse with attribution', 'Copied from the printed state-wise table (page 366). Period labelled 2021-22 because NHP Table 6.1.1 gives the same India totals (648 colleges, 98013 seats) as "2021-22* (upto September 2022)".', '33 states/UTs + India; 2021-22 (as on September 2022)', 'The Govt/Pvt college split printed for Maharashtra (62/1) and Tamil Nadu (65/6) is clearly wrong (both states have many private colleges; the seat split printed in the same rows is about half private), and the India Govt/Pvt total (396/252) inherits that error, so Govt/Private college counts for MH, TN and India were NOT used for this edition; their totals and seats were kept. Row "D& N Haveli" left out (merged UT name not printed). Nagaland printed 0.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('cbhi-nhp-2023-t611b', 'Central Bureau of Health Intelligence (DGHS, MoHFW); original source: National Medical Commission website', 'National Health Profile 2023, Table 6.1.1(b): State-wise distribution of Medical Colleges and MBBS seats as on 30.06.2023', 'https://cbhidghs.mohfw.gov.in/sites/default/files/NHP/NHP-2023-Last-Final.pdf', 'A', 'Government of India publication (CBHI, DGHS, MoHFW); reuse with attribution', 'Govt / "Pvt., Trust & Society" / Total colleges and seats copied from the printed state-wise table (page 229). Labelled 2022-23 because NHP Table 6.1.1 gives the same India totals (679 colleges, 104163 seats) for 2022-23.', '33 states/UTs + India; 2022-23 (as on 30.06.2023)', 'Private column = private, trust and society colleges combined (as printed). The merged UT is printed as "Dadra and Nagar Haveli" in this table (but as "Dadra and Nagar Haveli and Daman & Diu" in Table 6.1.1(a)); left out of the rows to be safe. ', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('ls-18-as76-2024-07-26', 'Lok Sabha, Ministry of Health and Family Welfare (data from National Medical Commission)', 'Lok Sabha Starred Question No. 76 "New Medical Colleges", answered 26.07.2024, Annexure-I', 'https://sansad.in/getFile/lsapps/loksabhaquestions/annex/182/AS76_SLumeS.pdf?source=lsapps', 'A', 'Parliament of India (Lok Sabha) question answer; public record, reuse with attribution', 'Only the 2018-19 columns (number of colleges, number of seats) were used; the 2023-24 and 2024-25 columns are superseded by later answers. Printed Total row used for India.', '32 states/UTs + India; 2018-19', 'Govt/Private split not given. Dadra & Nagar Haveli and Daman & Diu and Nagaland printed "-" for 2018-19 (left out). J&K includes Ladakh. Total 499 colleges / 70012 seats differs from NHP Table 6.1.1 (529 colleges for 2018-19).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('ls-18-au847-2025-02-07', 'Lok Sabha, Ministry of Health and Family Welfare (data from National Medical Commission)', 'Lok Sabha Unstarred Question No. 847 "Medical Colleges", answered 07.02.2025, Annexure', 'https://sansad.in/getFile/lsapps/loksabhaquestions/annex/184/AU847_lVl2i3.pdf?source=lsapps', 'A', 'Parliament of India (Lok Sabha) question answer; public record, reuse with attribution', 'AY 2014-15 column copied; India total from the answer text (54,348 seats in 2014).', '32 states/UTs + India; 2014-15', 'State rows for 2014-15 exclude AIIMS (673 seats printed as a separate AIIMS row); the India total in the text presumably includes them. Andhra Pradesh is undivided (Telangana printed 0 and left out). Dadra & Nagar Haveli left out. AY 2024-25 column not used (superseded by LS Q.1099 of 2026).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('ls-18-au5703-2026-03-27', 'Lok Sabha, Ministry of Health and Family Welfare (data from National Medical Commission)', 'Lok Sabha Unstarred Question No. 5703 "Medical Colleges Opened by NMC", answered 27.03.2026, Annexure: Total number of State/UT wise UG medical colleges for the last five years', 'https://sansad.in/getFile/lsapps/loksabhaquestions/annex/187/AU5703_eWTI71.pdf?source=lsapps', 'A', 'Parliament of India (Lok Sabha) question answer; public record, reuse with attribution', 'Number of UG (MBBS) medical colleges by state for AY 2021-22 to 2025-26 copied from the annexure.', '33 states/UTs; 2021-22 to 2025-26', 'No India total row; Govt/Private split not given; Dadra & Nagar Haveli row left out (merged UT name not printed).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('ls-18-au3650-2026-03-13', 'Lok Sabha, Ministry of Health and Family Welfare (data from National Medical Commission)', 'Lok Sabha Unstarred Question No. 3650 "MBBS and PG Medical Seats", answered 13.03.2026, Annexure-I: State/UT wise medical colleges across the country', 'https://sansad.in/getFile/lsapps/loksabhaquestions/annex/187/AU3650_4sLLrK.pdf?source=lsapps', 'A', 'Parliament of India (Lok Sabha) question answer; public record, reuse with attribution', 'Private / Govt / Total colleges by state copied; India total (818, including AIIMS and INIs) from the answer text. Labelled 2025-26 ("as of now", March 2026).', '33 states/UTs (+ India total colleges only); 2025-26', 'No India Govt/Private split printed. Dadra & Nagar Haveli row left out. Private is not broken down into trust/society/deemed.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('ls-18-au1099-2026-07-24', 'Lok Sabha, Ministry of Health and Family Welfare (data from National Medical Commission)', 'Lok Sabha Unstarred Question No. 1099 "Regional Availability of Medical Seats and Doctors", answered 24.07.2026, Annexure-I: MBBS seats by State/UT, AY 2023-24 to 2025-26', 'https://sansad.in/getFile/lsapps/loksabhaquestions/annex/188/AU1099_NAGDiV.pdf?source=lsapps', 'A', 'Parliament of India (Lok Sabha) question answer; public record, reuse with attribution', 'MBBS seats by state for three academic years copied from Annexure-I (read with pdftotext -table; the -layout rendering misaligns the first column). India totals for 2023-24 and 2025-26 from the answer text.', '33 states/UTs + India (2023-24, 2025-26); 2023-24 to 2025-26', 'No India total for 2024-25; no Govt/Private split; Dadra & Nagar Haveli left out.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('nmc-mbbs-college-list-2026-10', 'National Medical Commission', 'NMC "List of College Teaching MBBS" (college-level list with state, management type and approved seats)', 'https://www.nmc.org.in/page/information-desk-for-students-to-study-in-india-list-of-college-teaching-mbbs', 'A', 'NMC website content; reuse with attribution', 'The page loads its table from https://www.nmc.org.in/college-courses/list?page=N&per_page=500 (2 pages, 834 MBBS records, one per college). Colleges counted and approved_seat summed by state_name and management_type (Government vs Private; one "Trust" college counted as private). The endpoint total_seats (140314) equals the sum. Labelled AY 2026-27 (records carry renewals "for the AY 2026-27", last updated Sep-Oct 2026).', '35 states/UTs + India; 2026-27 snapshot pulled 16.10.2026', 'The NMC list does not include AIIMS, JIPMER and other Institutes of National Importance, so Government counts and seats are lower than in MoHFW answers that include them (break flagged). It is a live list and changes over time. "Dadra and Nagar Haveli" college left out of state rows (included in India).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('nirf-2017-overall', 'National Institutional Ranking Framework (NIRF), Ministry of Education', 'NIRF India Rankings 2017: Overall ranking', 'https://www.nirfindia.org/Rankings/2017/OverallRanking.html', 'A', 'Ministry of Education website content; reuse with attribution', 'Ranking table parsed from the HTML (institute ID, name, city, state, score, rank); institutions with rank 1-100 counted by the State column. States with no institution in the top 100 get 0.', 'All states/UTs + India; 2017', 'Counts are of institutions by the state printed in the list (campus location of the ranked entity). Ties can push the number listed with rank <=100 slightly above or the top rank number below 100. Overall ranking started in 2017 (the 2016 URL serves the 2017 list and was not used).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
