insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('nirf-2021-overall', 'National Institutional Ranking Framework (NIRF), Ministry of Education', 'NIRF India Rankings 2021: Overall ranking', 'https://www.nirfindia.org/Rankings/2021/OverallRanking.html', 'A', 'Ministry of Education website content; reuse with attribution', 'Ranking table parsed from the HTML (institute ID, name, city, state, score, rank); institutions with rank 1-100 counted by the State column. States with no institution in the top 100 get 0.', 'All states/UTs + India; 2021', 'Counts are of institutions by the state printed in the list (campus location of the ranked entity). Ties can push the number listed with rank <=100 slightly above or the top rank number below 100. Overall ranking started in 2017 (the 2016 URL serves the 2017 list and was not used).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
