insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('moe-udiseplus-2018-19', 'Ministry of Education, Department of School Education & Literacy (UDISE+)', 'Report on UDISE+ 2018-19: Table 1.1: Number of schools by level of school education, 2018-19; Table 5.1: Gross Enrolment Ratio (GER) by Gender and Level of School Education, 2018-19; Table 2.11: Pupil Teacher Ratio (PTR) by level of school education, 2018-19', 'https://dashboard.udiseplus.gov.in/report2026/static/media/UDISE+2018_19_Booklet.61e6bf9d5e445574ee1d.docx', 'A', 'Government of India publication on the UDISE+ dashboard; no explicit open licence stated in the file; reuse with attribution to Ministry of Education, UDISE+', 'Downloaded from the UDISE+ dashboard report bundle (dashboard.udiseplus.gov.in, Reports). Table text read from the Word file XML. Values copied exactly as printed: schools = Total column of the schools-by-level table (all managements); GER = Secondary (9-10) Total, All Social Groups; PTR = Secondary (9-10). Checks: school Total equals the sum of the four levels and GER total lies between boys and girls in every row.', 'India plus 35 States/UTs, academic year 2018-19', 'Dadra & Nagar Haveli and Daman & Diu are printed separately in this edition and were left out (no DH value). Ladakh printed as a separate row from Jammu & Kashmir. Published on the UDISE+ dashboard as a Word (.docx) file; no page numbers taken. GER denominators are population projections based on the MoHFW Expert Group report (2020), as stated in the report; GER can exceed 100 or move with projection revisions. Secondary PTR printed as whole numbers in every edition except 2019-20 (one decimal).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('moe-udiseplus-2019-20', 'Ministry of Education, Department of School Education & Literacy (UDISE+)', 'Report on UDISE+ 2019-20: Table 1.1: Number of schools by level of school education, 2019-20; Table 5.1: Gross Enrolment Ratio (GER) by Gender and Level of school education, 2019-20; Table 2.11: Pupil Teacher Ratio (PTR) by level of school education, 2019-20', 'https://dashboard.udiseplus.gov.in/report2026/static/media/UDISE+2019_20_Booklet.2fea294ea7332fcb5f0c.pdf', 'A', 'Government of India publication on the UDISE+ dashboard; no explicit open licence stated in the file; reuse with attribution to Ministry of Education, UDISE+', 'Downloaded from the UDISE+ dashboard report bundle (dashboard.udiseplus.gov.in, Reports). Text extracted with pdftotext -table. Values copied exactly as printed: schools = Total column of the schools-by-level table (all managements); GER = Secondary (9-10) Total, All Social Groups; PTR = Secondary (9-10). Checks: school Total equals the sum of the four levels and GER total lies between boys and girls in every row.', 'India plus 35 States/UTs, academic year 2019-20', 'Dadra & Nagar Haveli and Daman & Diu are printed separately in this edition and were left out (no DH value). Ladakh printed as a separate row from Jammu & Kashmir. GER denominators are population projections based on the MoHFW Expert Group report (2020), as stated in the report; GER can exceed 100 or move with projection revisions. Secondary PTR printed as whole numbers in every edition except 2019-20 (one decimal).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
