insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('moe-udiseplus-2025-26', 'Ministry of Education, Department of School Education & Literacy (UDISE+)', 'Report on UDISE+ 2025-26 (existing-structure booklet): Table 3.1: Number of schools by level of school education, 2025-26; Table 6.1: Gross Enrolment Ratio (GER) by Gender and Level of School Education, 2025-26: All Social Groups; Table 4.12: Pupil Teacher Ratio (PTR) by level of school education, 2025-26', 'https://dashboard.udiseplus.gov.in/report2026/static/media/UDISE+2025_26_Booklet_existing.edd7cd16d934a10377ba.pdf', 'A', 'Government of India publication on the UDISE+ dashboard; no explicit open licence stated in the file; reuse with attribution to Ministry of Education, UDISE+', 'Downloaded from the UDISE+ dashboard report bundle (dashboard.udiseplus.gov.in, Reports). Text extracted with pdftotext -table. Values copied exactly as printed: schools = Total column of the schools-by-level table (all managements); GER = Secondary (9-10) Total, All Social Groups; PTR = Secondary (9-10). Checks: school Total equals the sum of the four levels and GER total lies between boys and girls in every row.', 'India plus 36 States/UTs, academic year 2025-26', 'Report states that from 2022-23 data are collected student-wise (not school-consolidated) and population projections were moderated using SRS birth-rate trends, UIDAI Aadhaar saturation and neighbouring-state trends, so GER/PTR are not strictly comparable with 2021-22 and earlier (break flagged at 2022-23). The existing-structure edition is used (Secondary = classes IX-X); the separate NEP-structure edition groups Secondary as IX-XII. GER denominators are population projections based on the MoHFW Expert Group report (2020), as stated in the report; GER can exceed 100 or move with projection revisions. Secondary PTR printed as whole numbers in every edition except 2019-20 (one decimal).', '2026-10-1