insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('aishe-2012-13-final', 'Ministry of Education (Ministry of Human Resource Development before 2020), Department of Higher Education - All India Survey on Higher Education (AISHE)', 'All India Survey on Higher Education 2012-13 - Final Report (Table 1 universities by State/UT and type; Table 4 colleges per lakh population 18-23; Table 19 GER 18-23 by State/UT)', 'https://cdnbbsr.s3waas.gov.in/s392049debbe566ca5782a3045cf300a3c/uploads/2025/06/20250604192794875.pdf', 'A', 'Government of India publication on aishe.gov.in; no explicit open licence stated in the PDF; reuse with attribution', 'PDF downloaded from the AISHE Final Report page (https://aishe.gov.in/aishe-final-report/) and converted with pdftotext -table; values copied as printed. Colleges per lakh = column 4 of Table 4; GER = All Categories Total column of Table 19; universities = Grand Total column of Table 1. 18-23 population: pre-2011-census projections. The report itself does not name the base; the 2020-21 report says the 2019-20 GER of 27.1 was as per 2001 population projection, and the 2019-20 report Table 47 repeats the 2015-16 to 2018-19 All-India GER exactly as first published (24.5, 25.2, 25.8, 26.3), so 2012-13 to 2019-20 reports are treated as one consistent series.', 'All-India and States/UTs as printed in the 2012-13 report', 'College density and GER depend on the 18-23 population projection used by the report; the projection base changed with the 2020-21 report (break). Densities are printed as whole numbers. Jammu & Kashmir includes Ladakh. Dadra & Nagar Haveli and Daman & Diu printed separately: left out. States with no university (e.g. Lakshadweep, A&N, DNH/DD) have no Table 1 row. Lakshadweep blank in Table 4 where it had no college. Universities counted are those listed/registered in AISHE for that year (coverage of the survey grew over time).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('aishe-2013-14-final', 'Ministry of Education (Ministry of Human Resource Development before 2020), Department of Higher Education - All India Survey on Higher Education (AISHE)', 'All India Survey on Higher Education 2013-14 - Final Report (Table 1 universities by State/UT and type; Table 4 colleges per lakh population 18-23; Table 19 GER 18-23 by State/UT)', 'https://cdnbbsr.s3waas.gov.in/s392049debbe566ca5782a3045cf300a3c/uploads/2025/06/202506041593835380.pdf', 'A', 'Government of India publication on aishe.gov.in; no explicit open licence stated in the PDF; reuse with attribution', 'PDF downloaded from the AISHE Final Report page (https://aishe.gov.in/aishe-final-report/) and converted with pdftotext -table; values copied as printed. Colleges per lakh = column 4 of Table 4; GER = All Categories Total column of Table 19; universities = Grand Total column of Table 1. 18-23 population: pre-2011-census projections. The report itself does not name the base; the 2020-21 report says the 2019-20 GER of 27.1 was as per 2001 population projection, and the 2019-20 report Table 47 repeats the 2015-16 to 2018-19 All-India GER exactly as first published (24.5, 25.2, 25.8, 26.3), so 2012-13 to 2019-20 reports are treated as one consistent series.', 'All-India and States/UTs as printed in the 2013-14 report', 'College density and GER depend on the 18-23 population projection used by the report; the projection base changed with the 2020-21 report (break). Densities are printed as whole numbers. Jammu & Kashmir includes Ladakh. Dadra & Nagar Haveli and Daman & Diu printed separately: left out. States with no university (e.g. Lakshadweep, A&N, DNH/DD) have no Table 1 row. Lakshadweep blank in Table 4 where it had no college. Universities counted are those listed/registered in AISHE for that year (coverage of the survey grew over time).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('aishe-2014-15-final', 'Ministry of Education (Ministry of Human Resource Development before 2020), Department of Higher Education - All India Survey on Higher Education (AISHE)', 'All India Survey on Higher Education 2014-15 - Final Report (Table 1 universities by State/UT and type; Table 4 colleges per lakh population 18-23; Table 19 GER 18-23 by State/UT)', 'https://cdnbbsr.s3waas.gov.in/s392049debbe566ca5782a3045cf300a3c/uploads/2025/06/202506041473712372.pdf', 'A', 'Government of India publication on aishe.gov.in; no explicit open licence stated in the PDF; reuse with attribution', 'PDF downloaded from the AISHE Final Report page (https://aishe.gov.in/aishe-final-report/) and converted with pdftotext -table; values copied as printed. Colleges per lakh = column 4 of Table 4; GER = All Categories Total column of Table 19; universities = Grand Total column of Table 1. 18-23 population: pre-2011-census projections. The report itself does not name the base; the 2020-21 report says the 2019-20 GER of 27.1 was as per 2001 population projection, and the 2019-20 report Table 47 repeats the 2015-16 to 2018-19 All-India GER exactly as first published (24.5, 25.2, 25.8, 26.3), so 2012-13 to 2019-20 reports are treated as one consistent series.', 'All-India and States/UTs as printed in the 2014-15 report', 'College density and GER depend on the 18-23 population projection used by the report; the projection base changed with the 2020-21 report (break). Densities are printed as whole numbers. Jammu & Kashmir includes Ladakh. Dadra & Nagar Haveli and Daman & Diu printed separately: left out. States with no university (e.g. Lakshadweep, A&N, DNH/DD) have no Table 1 row. Lakshadweep blank in Table 4 where it had no college. Universities counted are those listed/registered in AISHE for that year (coverage of the survey grew over time).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
