insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('census-actuarial-reports-1881-1951', 'Census of India (Office of the Registrar General); reprint volume with foreword by A. Mitra, 1960', 'Census of India: Actuarial Reports for the Census 1881, 1891, 1901, 1911, 1921, 1931 & 1951', 'https://censusindia.gov.in/nada/index.php/catalog/28100/download/31282/22439-1951-ACT.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'Census actuaries'' life tables derived from successive census age distributions, with assumed or registration-based mortality at infant and child ages.', 'Combined British Indian provinces investigated at each census (area varies by census); 1941-50 table for post-partition India.', 'Scanned; values read visually from page images. Pre-1931 tables cover selected provinces only; infant/child mortality largely assumed; the 1921 report gives no rates under age 5; no 1941 age tabulation. Male and female only (persons printed only for 1881).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('census-1971-life-tables-paper1-1977', 'Office of the Registrar General, India', 'Census of India 1971, Series 1 India, Paper 1 of 1977: Life Tables', 'https://censusindia.gov.in/nada/index.php/catalog/31289/download/34470/52738_1971_LIF.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'Life tables for 1961-70 from 1961 and 1971 census age data, compared with 1951-60 tables.', 'All-India and five zones.', 'Scanned; values read from page image. q0 based on SRS values/assumptions. Its Appendix C Table 5 mixes Kingsley Davis estimates (1921, 1941) with actuarial reports and was not used.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('census-1971-monograph9-literacy', 'Office of the Registrar General, India', 'Census of India 1971, Census Centenary Monograph No. 9: Extracts from the All India Census Reports on Literacy (D. Natarajan)', 'https://censusindia.gov.in/nada/index.php/catalog/30163/download/33344/26501_1971_CEN.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'ORGI statement of literates per 1,000 population at each census 1881-1971, plus extracts of the census reports.', '1881-1941 before partition (undivided India), 1951-1971 after partition.', 'Mixed definitions: 1881-1891 include ''learning''; the 1931 figure matches the 1931 report''s age 5+ ratio; 1941 provisional and possibly includes partial literacy. Scanned.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('mospi-women-men-2016-ch3', 'Ministry of Statistics and Programme Implementation (Central Statistics Office)', 'Women and Men in India 2016, Chapter 3: Literacy and Education', 'https://mospi.gov.in/sites/default/files/reports_and_publication/statistical_publication/social_statistics/WM16Chapter3.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'Reproduces Census of India (ORGI) literacy rates 1951-2011.', 'India, census years 1951-2011.', 'Official secondary reproduction; 1951 (18.32) and 1961 (28.31) differ by 0.01 from values commonly quoted (18.33, 28.30). Age base 5+ to 1971, 7+ from 1981; coverage exclusions in 1981, 1991, 2001.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('census-1941-paper3-infant-mortality', 'Census of India (Census Commissioner for India)', 'Census of India 1941, Paper No. 3 (1949): Probable Effect of Decrease in Infantile Mortality on Future Population (S. Swaroop)', 'https://censusindia.gov.in/nada/index.php/catalog/31437/download/34618/21310_1941_FUL.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'Annual infant mortality rates per 1,000 live births from registration areas of former British Indian provinces now in the Union of India, averaged to represent the Union of India, 1920-1946.', 'Union of India area (post-1947), 1920-1946.', 'Based on incomplete civil registration; 1920 value is unclear in the scan (195 or 196) and was omitted; not comparable with SRS.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hbs-2017-18-t1', 'Reserve Bank of India (Handbook of Statistics on the Indian Economy 2017-18); original source: Central Statistics Office (CSO), Ministry of Statistics and Programme Implementation', 'Table 1: Macro-Economic Aggregates (At Current Prices), base 2011-12 - Per Capita NNI (rupees)', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/TABLE103EBE23AD5EE4D6A9A62A9D939677B34.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Used for mospi_nni_pc_current (income_per_capita_current). ''Per Capita NNI'' row of the table (NNI divided by mid-financial-year population), 2011-12 base columns only. Each year of dataset mospi_nni_pc_current is taken from the latest HBS edition that still prints that year (editions 2017-18 to 2025-26 each print a 7-year window), so the series uses the most recent official estimate for every year. Values copied as displayed; where a cell holds an unrounded float the displayed integer is recorded and the raw value given in the row note.', 'All India; 2011-12; 1 values', 'Recent years are provisional or first/second revised estimates (status in each row note) and are revised in later editions. The 2011-12 base series is superseded by the base 2022-23 series released in 2026; HBS 2025-26 prints 2011-12-base figures only up to 2022-23. Not comparable with the 2004-05 or earlier base series (different methodology: NNI vs NNP at factor cost).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
