insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hbs-2025-26-t1', 'Reserve Bank of India (Handbook of Statistics on the Indian Economy 2025-26); original source: National Statistics Office (NSO), Ministry of Statistics and Programme Implementation', 'Table 1: Macro-Economic Aggregates (At Current Prices), base 2011-12 (2020-21 to 2022-23) and base 2022-23 (2022-23 to 2025-26) - Per Capita NNI (rupees)', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/1T_HBIE310720260FBAA53A59A94B94A78CB8313C150B62.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', '''Per Capita NNI'' row. Used for mospi_nni_pc_current: 2020-21 and 2021-22 from the base 2011-12 block (cols C-D) and 2022-23 to 2025-26 from the base 2022-23 block (cols F-I), break flagged at 2022-23. Values copied exactly.', 'All India; 2020-21, 2021-22, 2022-23, 2023-24, 2024-25, 2025-26; 6 values', 'Table prints both bases side by side for 2022-23 (2011-12 base: 2022-23 current 169145; 2022-23 base: 159557); the two are different series and are never mixed within a constant-price dataset. 2024-25 is First Revised and 2025-26 Provisional (table notes). The new base 2022-23 series has only four years; its back series had not been published in this edition.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hbs-2025-26-t2', 'Reserve Bank of India (Handbook of Statistics on the Indian Economy 2025-26); original source: National Statistics Office (NSO), Ministry of Statistics and Programme Implementation', 'Table 2: Macro-Economic Aggregates (At Constant Prices), base 2011-12 (2020-21 to 2022-23) and base 2022-23 (2022-23 to 2025-26) - Per Capita NNI (rupees)', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/2T_HBIE310720261ED415A38F9E465C9B9BEDEA897741FB.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', '''Per Capita NNI'' row. Used for mospi_nni_pc_2011: 2020-21 to 2022-23 from the base 2011-12 block (cols C-E); mospi_nni_pc_2022: 2022-23 to 2025-26 at constant 2022-23 prices from the base 2022-23 block (cols F-I). Values copied exactly.', 'All India; 2020-21, 2021-22, 2022-23, 2022-23, 2023-24, 2024-25, 2025-26; 7 values', 'Table prints both bases side by side for 2022-23 (2011-12 base: 2022-23 current 169145; 2022-23 base: 159557); the two are different series and are never mixed within a constant-price dataset. 2024-25 is First Revised and 2025-26 Provisional (table notes). The new base 2022-23 series has only four years; its back series had not been published in this edition.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hbs-2012-13-t1', 'Reserve Bank of India (Handbook of Statistics on the Indian Economy 2012-13); original source: Central Statistics Office (CSO), Ministry of Statistics and Programme Implementation', 'Table 1: Macroeconomic Aggregates (At Current Prices), base 2004-05 - Per Capita NNP at Factor Cost (rupees)', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/001T_BST130913.xls', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Used only for 1950-51 to 1965-66 of mospi_nni_pc_current (later editions start the 2004-05 block at 1966-67). Legacy .xls converted to .xlsx locally with Excel (macros disabled) to read cells; column V. ''Per Capita NNP at Factor Cost'' column of the base 2004-05 block (the per capita national income measure of that series). Values copied as displayed; where a cell holds an unrounded float the displayed integer is recorded and the raw value given in the row note.', 'All India; 1950-51 to 1965-66; 16 values', 'Base 2004-05 series (CSO back series to 1950-51); population from Census 2001 projections (HBS 2016-17 note 4). Discontinued after the 2011-12 base revision; not comparable with the 2011-12 base series (NNP at factor cost vs NNI; different methodology and population base). Values for 1950-51 to 2008-09 in this edition are identical to HBS 2016-17 wherever both print them.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hbs-2012-13-t2', 'Reserve Bank of India (Handbook of Statistics on the Indian Economy 2012-13); original source: Central Statistics Office (CSO), Ministry of Statistics and Programme Implementation', 'Table 2: Macroeconomic Aggregates (At constant prices), base 2004-05 - Per Capita NNP at Factor Cost (rupees)', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/002T_BST130913.xls', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Used only for 1950-51 to 1965-66 of mospi_nni_pc_2004. Legacy .xls converted to .xlsx locally with Excel (macros disabled); column R. ''Per Capita NNP at Factor Cost'' column of the base 2004-05 block (the per capita national income measure of that series). Values copied as displayed; where a cell holds an unrounded float the displayed integer is recorded and the raw value given in the row note.', 'All India; 1950-51 to 1965-66; 16 values', 'Base 2004-05 series (CSO back series to 1950-51); population from Census 2001 projections (HBS 2016-17 note 4). Discontinued after the 2011-12 base revision; not comparable with the 2011-12 base series (NNP at factor cost vs NNI; different methodology and population base). This edition also prints a provisional 2012-13 figure (39168), which was not used because the latest edition carrying the series ends at 2011-12 with revised 2010-11 and 2011-12 figures.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hbs-2016-17-t1', 'Reserve Bank of India (Handbook of Statistics on the Indian Economy 2016-17); original source: Central Statistics Office (CSO), Ministry of Statistics and Programme Implementation', 'Table 1: Macro-Economic Aggregates (At Current Prices), base 2004-05 block - Per Capita NNP at Factor Cost (rupees)', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/TABLE11BC2E287C4844BB792DA26F499968B21.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Used for 1966-67 to 2010-11 of mospi_nni_pc_current (2011-12 onward comes from the 2011-12 base). Latest HBS edition carrying the 2004-05 base series; column X. ''Per Capita NNP at Factor Cost'' column of the base 2004-05 block (the per capita national income measure of that series). Values copied as displayed; where a cell holds an unrounded float the displayed integer is recorded and the raw value given in the row note.', 'All India; 1966-67 to 2010-11; 45 values', 'Base 2004-05 series (CSO back series to 1950-51); population from Census 2001 projections (HBS 2016-17 note 4). Discontinued after the 2011-12 base revision; not comparable with the 2011-12 base series (NNP at factor cost vs NNI; different methodology and population base).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hbs-2016-17-t2', 'Reserve Bank of India (Handbook of Statistics on the Indian Economy 2016-17); original source: Central Statistics Office (CSO), Ministry of Statistics and Programme Implementation', 'Table 2: Macro-Economic Aggregates (At Constant Prices), base 2004-05 block - Per Capita NNP at Factor Cost (rupees)', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/TABLE2E50CC5251BC840E596D0D00A0F01FDFE.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Used for 1966-67 to 2011-12 of mospi_nni_pc_2004. Latest HBS edition carrying the 2004-05 base series; column S. ''Per Capita NNP at Factor Cost'' column of the base 2004-05 block (the per capita national income measure of that series). Values copied as displayed; where a cell holds an unrounded float the displayed integer is recorded and the raw value given in the row note.', 'All India; 1966-67 to 2011-12; 46 values', 'Base 2004-05 series (CSO back series to 1950-51); population from Census 2001 projections (HBS 2016-17 note 4). Discontinued after the 2011-12 base revision; not comparable with the 2011-12 base series (NNP at factor cost vs NNI; different methodology and population base).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hbs-2008-09-t2', 'Reserve Bank of India (Handbook of Statistics on the Indian Economy 2008-09); original source: Central Statistical Organisation (CSO), Ministry of Statistics and Programme Implementation', 'Table 2: Macro-economic Aggregates (At Constant Prices), base 1999-2000 - Per Capita NNP at Factor Cost (rupees)', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/2T_HB150909.xls', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Used for mospi_nni_pc_1999 (constant 1999-2000 prices, 1950-51 to 2008-09, incl. CSO back series). Last HBS edition before the 2004-05 base revision; it prints the whole 1999-2000 series. Legacy .xls converted to .xlsx locally with Excel (macros disabled); column V. Values copied as displayed; where a cell holds an unrounded float the displayed integer is recorded and the raw value given in the row note.', 'All India; 1950-51 to 2008-09; 59 values', '2006-07 Provisional, 2007-08 Quick Estimates, 2008-09 Revised Estimates (table note). Superseded by the 2004-05 base; not comparable with other bases. Current-price figures of this base were not taken (the current-price dataset uses the most recent base available for each year).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hbs-2006-t2', 'Reserve Bank of India (Handbook of Statistics on the Indian Economy edition released 18 Sep 2006); original source: Central Statistical Organisation (CSO), Ministry of Statistics and Programme Implementation', 'Table 2: Macro-economic aggregates (at constant prices), old series base 1993-94 - Per capita NNP at factor cost (rupees)', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/72632.xls', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Used for mospi_nni_pc_1993 (constant 1993-94 prices, 1950-51 to 2004-05; ''Old series (Base: 1993-94)'' block, sheet Page-10, column I). Last HBS edition printing the 1993-94 series. Legacy .xls converted to .xlsx locally with Excel (macros disabled). Values copied exactly; status letters (P/QE/RE) in column B recorded in the row note.', 'All India; 1950-51 to 2004-05; 55 values', '2002-03 P, 2003-04 QE, 2004-05 RE as printed (for 2004-05 only the per capita NNP figure is printed). Superseded by the 1999-2000 base series; not comparable with other bases. The edition''s title page year is not shown on the RBI listing page (release date 18 Sep 2006).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2023-24-t27', 'Reserve Bank of India (Handbook of Statistics on Indian States 2023-24); original source: National Statistical Office, Ministry of Statistics and Programme Implementation', 'Table 27: Per Capita Net State Domestic Product (Constant Prices), base 2004-05, 2004-05 to 2014-15 (sheets T_27(i), T_27(ii))', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/T27_091220249DE2BD95750C4B008E2223455DDD4E49.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Per capita NSDP at constant 2004-05 prices in rupees, base 2004-05 sheets only (the 2011-12 base sheets are already in rbi_nsdp_pc_2011). Latest HSIS edition that still prints the 2004-05 series. Values copied exactly; ''-'' (not available) skipped. Year = end year of the fiscal year.', '33 states/UTs; 2004-05 to 2014-15; 353 values', 'Telangana is printed separately for every year from 2004-05, so Andhra Pradesh figures are for residual AP throughout. Jammu & Kashmir includes Ladakh. No All-India, Ladakh, Lakshadweep or Dadra & Nagar Haveli/Daman & Diu rows. 2014-15 not available for 10 states/UTs. Not comparable with the 2011-12 base series.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2018-19-t16', 'Reserve Bank of India (Handbook of Statistics on Indian States 2018-19); original source: Central Statistics Office, Ministry of Statistics and Programme Implementation', 'Table 16: Per Capita Net State Domestic Product at Factor Cost (Constant Prices), base 1993-94 (1993-94 to 1999-00) and base 1999-2000 (1999-00 to 2004-05)', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/16TABLE361A1F6CA3C4444F8099F0E8D4FFB401.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Per capita NSDP at factor cost in rupees at constant prices of each base. Base 1993-94 columns -> dataset rbi_nsdp_pc_1993; base 1999-2000 columns -> rbi_nsdp_pc_1999; the 1999-00 year appears in both bases and is kept in each dataset separately (never spliced). Latest HSIS edition that prints these bases. Values copied exactly; ''-'' skipped. Year = end year.', '32 states/UTs; 1993-94 to 2004-05; 409 values', 'Andhra Pradesh is undivided (Telangana not available) and Jammu & Kashmir includes Ladakh in both bases. Chhattisgarh, Jharkhand and Uttarakhand have their own rows from 1993-94, which suggests Madhya Pradesh, Bihar and Uttar Pradesh figures are on present-day boundaries, but the table carries no footnote on territorial basis. Mizoram not available in the 1993-94 base. No All-India row. The 1980-81 base columns (1990-91 to 1992-93) were not taken.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2024-25-t19', 'Reserve Bank of India (Handbook of Statistics on Indian States 2024-25); original source: National Statistical Office, Ministry of Statistics and Programme Implementation', 'Table 19: Per Capita Net State Domestic Product (Current Prices, base 2011-12, rupees), 2011-12 to 2024-25', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/19T_11122025B8CC230E4A34431999B4D6A107707BCA.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Per capita NSDP at current prices in rupees, by fiscal year, as compiled by RBI from NSO/MoSPI. Values copied exactly; ''-'' skipped. Year = end year of the fiscal year. Check: every 2011-12 value equals the 2011-12 constant-price value in Table 20 (rbi_nsdp_pc_2011).', '34 states/UTs; 2011-12 to 2024-25; 455 values', 'Jammu & Kashmir includes Ladakh for 2011-12 to 2018-19 and is UT of J&K only from 2019-20 (break flagged). Ladakh has values only for 2022-23 and 2023-24. Telangana is listed from 2011-12, so Andhra Pradesh figures are for residual AP throughout. No All-India, Lakshadweep or Dadra & Nagar Haveli and Daman & Diu rows. Several states have no 2024-25 (Gujarat no 2023-24) figure; recent years are routinely revised.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2024-25-t144', 'Reserve Bank of India (Handbook of Statistics on Indian States 2024-25); original source: Ministry of Road Transport and Highways', 'Table 144: State-wise Length of National Highways (Kms), as at end-March, 2005-2024', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/144T_111220250497208D070C44219818788DB5BCE35A.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Excel downloaded with curl; every numeric cell copied exactly; "." (not applicable) skipped.', '36 rows (states/UTs + All India), 2005-2019 and 2021-2024 (2020 not available, table note)', '2022-2024 relate to end-December (table note *). Andhra Pradesh includes Telangana up to 2014. J&K row includes Ladakh. Large one-year jumps (e.g. 2016 to 2017, Maharashtra 7,435 to 16,239) are not explained; the table does not separate new construction from roads newly declared as NHs.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2024-25-t145', 'Reserve Bank of India (Handbook of Statistics on Indian States 2024-25); original source: Ministry of Railways', 'Table 145: State-wise Railway Route (Kms), as at end-March, 2004-2024', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/145T_111220259E033C52098E4732A6101C940DEF1222.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Excel downloaded with curl; numeric cells copied exactly; "." and "-" skipped.', 'States/UTs with railways + All India, 2004-2024', 'Andhra Pradesh includes Telangana up to 2013. Route km of all gauges; no electrified split.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('rbi-hsis-2024-25-t146', 'Reserve Bank of India (Handbook of Statistics on Indian States 2024-25); original source: Ministry of Road Transport and Highways', 'Table 146: State-wise Length of Roads (Kms), as at end-March, 2005-2020', 'https://rbidocs.rbi.org.in/rdocs/Publications/DOCs/146T_11122025B89449F4159B420E8305A9509F27FE82.XLSX', 'A', 'RBI website content; reuse with attribution to RBI and the original source (no explicit open licence stated in the file)', 'Excel downloaded with curl; numeric cells copied exactly.', 'States/UTs + All India, 2005-2020', 'All-India totals are lower than MoRTH Basic Road Statistics Table 1.6 for the same years (different coverage, e.g. JRY roads); do not mix the two. Dadra & Nagar Haveli and Daman & Diu printed separately and left out. Andhra Pradesh includes Telangana up to 2013. Several state series jump (e.g. 2009) without explanation.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('morth-brs-2020-22', 'Ministry of Road Transport and Highways (Transport Research Wing)', 'Basic Road Statistics of India 2020-21 & 2021-22', 'https://morth.nic.in/backend/documents/uploaded/Basic%20Road%20Statistics%20of%20India%202020_22.pdf', 'A', 'Government of India publication; reuse with attribution (no explicit open licence stated)', 'PDF downloaded with curl (file listed by the morth.nic.in reports API); text via pdftotext -raw/-layout; Table 1.3 (NH row) and Table 1.6 (total road) copied as printed.', 'All India: NH length 1950-51 to 2021-22 (decadal, then annual from 2019-20); total road length 1951-2022', 'Total road includes JRY roads. 1981 total printed with a typo ("1,4,85,421"). No state rows used.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('es-2025-26-sa-t1.26', 'Ministry of Finance (Economic Survey 2025-26, Statistical Appendix); source: Ministry of Railways', 'Table 1.26: Operations of Indian Railways', 'https://www.indiabudget.gov.in/economicsurvey/doc/stat/tab1.26.pdf', 'A', 'Government of India publication; reuse with attribution (no explicit open licence stated)', 'PDF via curl; pdftotext -raw; route km (total and electrified) copied, converted from thousand km to km.', 'All India 2020-21 to 2024-25', 'Printed in thousand km with 1-2 decimals, so values are rounded to 10-100 km. Electrified = operational (energised) lines (table note $). 2025-26 partial year not used.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('es-2025-26-sa-t1.29', 'Ministry of Finance (Economic Survey 2025-26, Statistical Appendix); source: Ministry of Civil Aviation', 'Table 1.29: Growth of Civil Aviation', 'https://www.indiabudget.gov.in/economicsurvey/doc/stat/tab1.29.pdf', 'A', 'Government of India publication; reuse with attribution (no explicit open licence stated)', 'PDF via curl; pdftotext -layout; row "Total at Indian airports" (passengers handled, lakh) copied and divided by 10 to give million.', 'All India 2013-14 to 2024-25', 'Passengers handled at airports count each passenger at departure and arrival, so it is about twice the number carried by airlines. 2025-26 (P) partial year not used.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('aai-traffic-mar2022', 'Airports Authority of India', 'Air Traffic Report, March 2022 (Traffic News summary)', 'https://www.aai.aero/sites/default/files/traffic-news/TRMar2k22.pdf', 'A', 'Government of India publication; reuse with attribution (no explicit open licence stated)', 'PDF via curl; pdftotext -table; April-March passenger totals (million) copied.', 'All India FY 2021-22 and 2020-21', 'March-report figures are provisional.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
