insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('ls-17-usq3002-2022-mohua', 'Lok Sabha Secretariat (reply of the Ministry of Housing and Urban Affairs)', 'Lok Sabha USQ 3002 (04.08.2022): Length of Metro Network', 'https://sansad.in/getFile/lsapps/loksabhaquestions/annex/179/AU3002.pdf?source=lsapps', 'A', 'Government of India publication; reuse with attribution (no explicit open licence stated)', 'PDF downloaded from sansad.in via the Lok Sabha questions API; text read with pdftotext -table; values copied as printed', 'Operational metro before 2014 (till Dec 2013), city-wise', 'Says 229 km before 2014; a 2024 reply says 248 km. Cities other than Delhi & NCR, Kolkata, Bangalore not listed.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
