insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('tg-seo-2023', 'Planning Department, Government of Telangana (prepared with the Directorate of Economics and Statistics, Telangana)', 'Telangana Socio Economic Outlook 2023 (Annexure 17: Demographic Details of Telangana; Annexure 22: Literacy Rates by Districts, 2011 Census)', 'https://www.nitiforstates.gov.in/public-assets/Policy/policy_files/RSSNAM000500.pdf', 'A', 'Government of India / State Government publication; reuse with attribution to the source', 'Printed Census 2011 literacy rate for Telangana (source line: Registrar General and Census Commissioner, India), transcribed as printed from Annexure 17(f), PDF p. 272 (printed 268); cross-checked against Annexure 22 State row (PDF p. 277) and Annexures 18/20/21 counts.', 'Telangana, Census 1961-2011 (state); 33 present-day districts for 2011', 'Copy retrieved from NITI Aayog''s NITI for States repository (nitiforstates.gov.in), not from telangana.gov.in directly. Figures refer to present-day Telangana: the printed 2011 population (3,50,03,674) is 190,304 lower than the 10 districts as constituted in 2011 in the Census PCA (35,193,978); a 2011-boundary calculation from PCA gives 66.46 instead of 66.54. Census literacy = literates aged 7+ / population aged 7+.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('mospi-plfs-ar-2017-18', 'National Statistical Office, Ministry of Statistics and Programme Implementation (MoSPI), Government of India', 'Annual Report, Periodic Labour Force Survey (PLFS), July 2017-June 2018', 'https://www.mospi.gov.in/sites/default/files/publication_reports/Annual%20Report%2C%20PLFS%202017-18_31052019.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'Household sample survey (stratified multi-stage design; first-stage units are census villages in rural areas and UFS blocks in urban areas). Values transcribed as printed from Table (7), PDF p. 151 (printed A-13): literacy rate (per cent), persons, rural+urban, age 7 years and above (col. 6).', 'All-India and States/UTs, July 2017-June 2018', 'Sample survey estimates, not a census count: state/UT values carry sampling error that the table does not print, and small States/UTs (e.g. Delhi, Goa, Chandigarh, Lakshadweep, A&N, Ladakh) rest on small samples (the 2022-23 report prints under 100 sample persons for Delhi, Chandigarh and Lakshadweep in its state education-distribution table), so year-to-year moves of a few points may be noise. Sample: 1,02,113 households; 4,33,339 persons (all-India). Literacy is self/household-reported ability to read and write a simple message with understanding in any language, not tested. Not comparable with Census literacy (different method, reference period and population frame). No separate Ladakh row (Jammu & Kashmir includes Ladakh). Dadra & Nagar Haveli and Daman & Diu printed separately; omitted (no DH code).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('mospi-plfs-ar-2018-19', 'National Statistical Office, Ministry of Statistics and Programme Implementation (MoSPI), Government of India', 'Annual Report, Periodic Labour Force Survey (PLFS), July 2018-June 2019', 'https://www.mospi.gov.in/sites/default/files/publication_reports/Annual_Report_PLFS_2018_19_HL.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'Household sample survey (stratified multi-stage design; first-stage units are census villages in rural areas and UFS blocks in urban areas). Values transcribed as printed from Table (7), PDF p. 120 (printed A-13): literacy rate (per cent), persons, rural+urban, age 7 years and above (col. 6).', 'All-India and States/UTs, July 2018-June 2019', 'Sample survey estimates, not a census count: state/UT values carry sampling error that the table does not print, and small States/UTs (e.g. Delhi, Goa, Chandigarh, Lakshadweep, A&N, Ladakh) rest on small samples (the 2022-23 report prints under 100 sample persons for Delhi, Chandigarh and Lakshadweep in its state education-distribution table), so year-to-year moves of a few points may be noise. Sample: 1,01,579 households; 4,20,757 persons (all-India). Literacy is self/household-reported ability to read and write a simple message with understanding in any language, not tested. Not comparable with Census literacy (different method, reference period and population frame). No separate Ladakh row (Jammu & Kashmir includes Ladakh). Dadra & Nagar Haveli and Daman & Diu printed separately; omitted (no DH code).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('mospi-plfs-ar-2019-20', 'National Statistical Office, Ministry of Statistics and Programme Implementation (MoSPI), Government of India', 'Annual Report, Periodic Labour Force Survey (PLFS), July 2019-June 2020', 'https://www.mospi.gov.in/sites/default/files/publication_reports/Annual_Report_PLFS_2019_20F1.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'Household sample survey (stratified multi-stage design; first-stage units are census villages in rural areas and UFS blocks in urban areas). Values transcribed as printed from Table (7), PDF p. 129 (printed A-13): literacy rate (per cent), persons, rural+urban, age 7 years and above (col. 6).', 'All-India and States/UTs, July 2019-June 2020', 'Sample survey estimates, not a census count: state/UT values carry sampling error that the table does not print, and small States/UTs (e.g. Delhi, Goa, Chandigarh, Lakshadweep, A&N, Ladakh) rest on small samples (the 2022-23 report prints under 100 sample persons for Delhi, Chandigarh and Lakshadweep in its state education-distribution table), so year-to-year moves of a few points may be noise. Sample: 1,00,480 households; 4,18,297 persons (all-India). Literacy is self/household-reported ability to read and write a simple message with understanding in any language, not tested. Not comparable with Census literacy (different method, reference period and population frame). Dadra & Nagar Haveli and Daman & Diu printed separately; omitted (no DH code). Jammu & Kashmir and Ladakh printed separately.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('mospi-plfs-ar-2020-21', 'National Statistical Office, Ministry of Statistics and Programme Implementation (MoSPI), Government of India', 'Annual Report, Periodic Labour Force Survey (PLFS), July 2020-June 2021', 'https://www.mospi.gov.in/sites/default/files/publication_reports/Annual_Report_PLFS_2020%2021_0.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'Household sample survey (stratified multi-stage design; first-stage units are census villages in rural areas and UFS blocks in urban areas). Values transcribed as printed from Table (7), PDF p. 132 (printed A-13): literacy rate (per cent), persons, rural+urban, age 7 years and above (col. 6).', 'All-India and States/UTs, July 2020-June 2021', 'Sample survey estimates, not a census count: state/UT values carry sampling error that the table does not print, and small States/UTs (e.g. Delhi, Goa, Chandigarh, Lakshadweep, A&N, Ladakh) rest on small samples (the 2022-23 report prints under 100 sample persons for Delhi, Chandigarh and Lakshadweep in its state education-distribution table), so year-to-year moves of a few points may be noise. Sample: 1,00,344 households; 4,10,818 persons (all-India). Literacy is self/household-reported ability to read and write a simple message with understanding in any language, not tested. Not comparable with Census literacy (different method, reference period and population frame). COVID-19: fieldwork suspended/delayed; most revisit schedules canvassed by telephone (section 1.2).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('mospi-plfs-ar-2021-22', 'National Statistical Office, Ministry of Statistics and Programme Implementation (MoSPI), Government of India', 'Annual Report, Periodic Labour Force Survey (PLFS), July 2021-June 2022', 'https://www.mospi.gov.in/sites/default/files/publication_reports/AnnualReportPLFS2021-22F1.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'Household sample survey (stratified multi-stage design; first-stage units are census villages in rural areas and UFS blocks in urban areas). Values transcribed as printed from Table (7), PDF p. 139 (printed A-13): literacy rate (per cent), persons, rural+urban, age 7 years and above (col. 6).', 'All-India and States/UTs, July 2021-June 2022', 'Sample survey estimates, not a census count: state/UT values carry sampling error that the table does not print, and small States/UTs (e.g. Delhi, Goa, Chandigarh, Lakshadweep, A&N, Ladakh) rest on small samples (the 2022-23 report prints under 100 sample persons for Delhi, Chandigarh and Lakshadweep in its state education-distribution table), so year-to-year moves of a few points may be noise. Sample: 1,01,782 households; 4,28,525 persons (all-India). Literacy is self/household-reported ability to read and write a simple message with understanding in any language, not tested. Not comparable with Census literacy (different method, reference period and population frame).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
