insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('mospi-plfs-ar-2023-24', 'National Statistical Office, Ministry of Statistics and Programme Implementation (MoSPI), Government of India', 'Annual Report, Periodic Labour Force Survey (PLFS), July 2023-June 2024', 'https://www.mospi.gov.in/sites/default/files/publication_reports/AnnualReport_PLFS2023-24L2.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'Household sample survey (stratified multi-stage design; first-stage units are census villages in rural areas and UFS blocks in urban areas). Values transcribed as printed from Table (7), PDF p. 73 (printed A-10): literacy rate (per cent), persons, rural+urban, age 7 years and above (col. 6).', 'All-India and States/UTs, July 2023-June 2024', 'Sample survey estimates, not a census count: state/UT values carry sampling error that the table does not print, and small States/UTs (e.g. Delhi, Goa, Chandigarh, Lakshadweep, A&N, Ladakh) rest on small samples (the 2022-23 report prints under 100 sample persons for Delhi, Chandigarh and Lakshadweep in its state education-distribution table), so year-to-year moves of a few points may be noise. Sample: 1,01,920 households; 4,18,159 persons (all-India). Literacy is self/household-reported ability to read and write a simple message with understanding in any language, not tested. Not comparable with Census literacy (different method, reference period and population frame).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('mospi-plfs-ar-2025', 'National Statistical Office, Ministry of Statistics and Programme Implementation (MoSPI), Government of India', 'Annual Report, Periodic Labour Force Survey (PLFS), January-December 2025', 'https://www.mospi.gov.in/uploads/publications_reports/publications_reports1780040415321_0624fb13-fb47-40bc-b470-7c7e9635c3ef_PLFS_2025_F_REV_29052026.pdf', 'A', 'Government of India publication; reuse with attribution to the source', 'Household sample survey (stratified multi-stage design; first-stage units are census villages in rural areas and UFS blocks in urban areas). Values transcribed as printed from Table (7), PDF p. 87 (printed A-10): literacy rate (per cent), persons, rural+urban, age 7 years and above (col. 6).', 'All-India and States/UTs, January-December 2025', 'Sample survey estimates, not a census count: state/UT values carry sampling error that the table does not print, and small States/UTs (e.g. Delhi, Goa, Chandigarh, Lakshadweep, A&N, Ladakh) rest on small samples (the 2022-23 report prints under 100 sample persons for Delhi, Chandigarh and Lakshadweep in its state education-distribution table), so year-to-year moves of a few points may be noise. Sample: 22,594 FSUs; 2,70,472 households; 11,48,634 persons (first visit) (all-India). Literacy is self/household-reported ability to read and write a simple message with understanding in any language, not tested. Not comparable with Census literacy (different method, reference period and population frame). Revamped sample design from January 2025 and calendar-year survey period; the report (para 1.3.1) cautions users when comparing with PLFS results up to December 2024. Series break flagged (break_before=1).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
