insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('nfhs5-compendium-phase2', 'IIPS / Ministry of Health and Family Welfare (copy hosted by The DHS Program, ICF)', 'NFHS-5 India and State Factsheet Compendium, Phase II (India + 14 states/UTs)', 'https://dhsprogram.com/pubs/pdf/OF43/NFHS-5_India_and_State_Factsheet_Compendium_Phase-II.pdf', 'A', 'Government of India publication', 'Household survey; fact sheets print NFHS-5 (2020-21; India 2019-21) and NFHS-4 (2015-16) side by side.', 'India and 14 states/UTs', 'Provisional fact-sheet results; survey estimates with sampling error.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('nfhs6-factsheets', 'International Institute for Population Sciences (IIPS) / Ministry of Health and Family Welfare', 'National Family Health Survey (NFHS-6), 2023-24: India and State/UT Fact Sheets (May 2026)', 'https://www.nfhsiips.in/nfhsuser/assets/National%20Family%20Health%20Survey%20(NFHS-6)%202023-2024%20Fact%20Sheets.pdf', 'A', 'Government of India publication', 'Household survey (679,238 households, 716,397 women, 100,977 men); fact sheets print NFHS-6 Urban/Rural/Total and NFHS-5 Total side by side. Total column used.', 'India and 35 states/UTs; Manipur not surveyed', 'Provisional results. The NFHS-6 fact sheets do not print improved sanitation or clean cooking fuel. Fieldwork ran from May 2023 to Dec 2024 in two phases, so state reference years differ (2023 or 2024).', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
