insert into public.sources (id, publisher, title, url, class, licence, method, coverage, limitations, last_checked) values ('dhs-api-WS_TLET_P_IMP', 'The DHS Program (ICF), tabulations of NFHS data (IIPS/MoHFW)', 'DHS Program Indicator Data API: Population with an improved sanitation facility (WS_TLET_P_IMP), India NFHS-1 to NFHS-5', 'https://api.dhsprogram.com/rest/dhs/data?countryIds=IA&indicatorIds=WS_TLET_P_IMP&breakdown=subnational&f=json&perpage=1000', 'B', 'The DHS Program data, free to use with attribution', 'DHS recalculation from NFHS microdata to DHS standard definitions. State values come from breakdown=subnational and India from breakdown=national (same query with breakdown=national). Surveys IA1993DHS, IA1999DHS, IA2006DHS, IA2015DHS, IA2020DHS; IsPreferred rows only.', 'States as surveyed in each round (25 in NFHS-1, 26 in NFHS-2, 29 in NFHS-3, 34 states/UTs in NFHS-4, 36 in NFHS-5) plus India', 'Values can differ slightly from printed NFHS reports (NFHS-4/5 checked: within 0.1 point of the fact sheets). DHS-built aggregates such as ''Bihar, inc Jharkhand'' for post-2000 rounds, NFHS-1 ''Jammu region'', and NFHS-4 separate DNH / Daman & Diu were skipped.', '2026-10-16') on conflict (id) do update set publisher = excluded.publisher, title = excluded.title, url = excluded.url, class = excluded.class, licence = excluded.licence, method = excluded.method, coverage = excluded.coverage, limitations = excluded.limitations, last_checked = excluded.last_checked;
